export const SAVE_KEY = 'time-rewind-save-v1';

/* ============================================================
   TIME REWIND — procedural audio engine (WebAudio, no assets)
   ============================================================ */

const CHORDS = [
  [55.0, 110.0, 164.81, 220.0, 246.94],
  [49.0, 98.0, 146.83, 196.0, 246.94],
  [43.65, 87.31, 130.81, 174.61, 220.0],
  [48.99, 97.99, 146.83, 196.0, 233.08]
];

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicBus = null;
    this.sfxBus = null;
    this.enabled = true;
    this.ready = false;
    this.level = 0;
    this.chord = 0;
    this.nextChordAt = 0;
    this.nextPulseAt = 0;
    this.rewindNodes = null;
    this.paused = false;
    this._unlock = this.unlock.bind(this);
    window.addEventListener('pointerdown', this._unlock, { passive: true });
    window.addEventListener('keydown', this._unlock);
  }

  unlock() {
    if (!this.ctx) {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      this.ctx = new Ctx();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.enabled ? 0.62 : 0;
      const comp = this.ctx.createDynamicsCompressor();
      comp.threshold.value = -18;
      comp.knee.value = 22;
      comp.ratio.value = 5;
      comp.attack.value = 0.006;
      comp.release.value = 0.26;
      this.master.connect(comp).connect(this.ctx.destination);

      this.musicBus = this.ctx.createGain();
      this.musicBus.gain.value = 0.17;
      this.musicBus.connect(this.master);

      this.sfxBus = this.ctx.createGain();
      this.sfxBus.gain.value = 0.5;
      this.sfxBus.connect(this.master);

      this.reverb = this.ctx.createConvolver();
      const len = this.ctx.sampleRate * 2.2;
      const impulse = this.ctx.createBuffer(2, len, this.ctx.sampleRate);
      for (let c = 0; c < 2; c++) {
        const data = impulse.getChannelData(c);
        for (let i = 0; i < len; i++) {
          data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 3.2);
        }
      }
      this.reverb.buffer = impulse;
      this.reverbGain = this.ctx.createGain();
      this.reverbGain.gain.value = 0.16;
      this.reverb.connect(this.reverbGain).connect(this.master);

      this.ready = true;
      this.nextChordAt = this.ctx.currentTime + 0.12;
      this.nextPulseAt = this.ctx.currentTime + 0.4;
    }
    if (this.ctx.state === 'suspended') this.ctx.resume();
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(on ? 0.62 : 0, this.ctx.currentTime + 0.14);
    }
    if (on) this.unlock();
  }

  setPaused(paused) {
    this.paused = paused;
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    this.musicBus.gain.cancelScheduledValues(t);
    this.musicBus.gain.linearRampToValueAtTime(paused ? 0.06 : 0.17, t + 0.4);
  }

  setLevel(index) {
    this.level = index;
    this.chord = index % CHORDS.length;
  }

  update() {
    if (!this.ready || !this.enabled || this.ctx.state !== 'running' || this.paused) return;
    const t = this.ctx.currentTime;
    while (this.nextChordAt < t + 0.3) {
      this.scheduleChord(this.nextChordAt);
      this.nextChordAt += 4.2;
    }
    while (this.nextPulseAt < t + 0.12) {
      if (Math.random() > 0.28) this.pulse(this.nextPulseAt);
      this.nextPulseAt += 0.5;
    }
  }

  scheduleChord(at) {
    const chord = CHORDS[(this.chord + Math.floor(at / 16.8)) % CHORDS.length];
    const filterFreq = 620 + (this.level % 5) * 90;
    for (let i = 0; i < chord.length; i++) {
      const freq = chord[i] * (i === 4 ? 1.5 : 1);
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      const filter = this.ctx.createBiquadFilter();
      osc.type = i < 2 ? 'sine' : 'triangle';
      osc.frequency.value = freq;
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(filterFreq, at);
      filter.frequency.linearRampToValueAtTime(filterFreq * 1.8, at + 1.6);
      filter.frequency.linearRampToValueAtTime(filterFreq * 0.7, at + 4.4);
      filter.Q.value = 1.4;
      const vol = i === 0 ? 0.017 : 0.012 / Math.max(1, i * 0.45);
      gain.gain.setValueAtTime(0.0001, at);
      gain.gain.exponentialRampToValueAtTime(vol, at + 0.6);
      gain.gain.exponentialRampToValueAtTime(0.0001, at + 4.5);
      osc.connect(filter).connect(gain);
      gain.connect(this.musicBus);
      gain.connect(this.reverb);
      osc.start(at);
      osc.stop(at + 4.6);
    }
    // Airy high shimmer
    const shimmer = this.ctx.createOscillator();
    const sg = this.ctx.createGain();
    shimmer.type = 'sine';
    shimmer.frequency.setValueAtTime(chord[4] * 2, at);
    shimmer.frequency.linearRampToValueAtTime(chord[4] * 2.02, at + 4);
    sg.gain.setValueAtTime(0.0001, at);
    sg.gain.exponentialRampToValueAtTime(0.005, at + 1.2);
    sg.gain.exponentialRampToValueAtTime(0.0001, at + 4.1);
    shimmer.connect(sg).connect(this.musicBus);
    shimmer.start(at);
    shimmer.stop(at + 4.2);
  }

  pulse(at) {
    const chord = CHORDS[(this.chord + Math.floor(at / 16.8)) % CHORDS.length];
    const freq = chord[3] * 2;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(freq, at);
    osc.frequency.exponentialRampToValueAtTime(freq * 0.5, at + 0.32);
    gain.gain.setValueAtTime(0.0001, at);
    gain.gain.exponentialRampToValueAtTime(0.013, at + 0.03);
    gain.gain.exponentialRampToValueAtTime(0.0001, at + 0.36);
    osc.connect(gain).connect(this.musicBus);
    gain.connect(this.reverb);
    osc.start(at);
    osc.stop(at + 0.38);
  }

  tone(freq, dur = 0.15, type = 'sine', vol = 0.08, slide = null, delay = 0) {
    if (!this.ready || !this.enabled) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slide), t + dur);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(vol, t + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(gain);
    gain.connect(this.sfxBus);
    gain.connect(this.reverb);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  noise(dur = 0.2, vol = 0.05, freq = 900, delay = 0, type = 'lowpass') {
    if (!this.ready || !this.enabled) return;
    const t = this.ctx.currentTime + delay;
    const length = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
    const src = this.ctx.createBufferSource();
    src.buffer = buffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t);
    filter.frequency.exponentialRampToValueAtTime(Math.max(80, freq * 0.35), t + dur);
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol, t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter).connect(gain);
    gain.connect(this.sfxBus);
    src.start(t);
  }

  click() {
    this.tone(880, 0.05, 'square', 0.026, 660);
  }

  jump() {
    this.tone(310, 0.13, 'triangle', 0.06, 560);
    this.noise(0.08, 0.016, 1600);
  }

  land() {
    this.tone(110, 0.09, 'sine', 0.045, 60);
    this.noise(0.07, 0.02, 420);
  }

  core() {
    const base = 660;
    [0, 0.07, 0.14, 0.24].forEach((d, i) => this.tone(base * [1, 1.25, 1.5, 2][i], 0.3, 'sine', 0.055, null, d));
  }

  energy() {
    this.tone(420, 0.15, 'square', 0.03, 840);
    this.tone(840, 0.2, 'sine', 0.04, 1100, 0.05);
  }

  checkpoint() {
    [220, 330, 440, 660].forEach((f, i) => this.tone(f, 0.4, 'sine', 0.04, null, i * 0.08));
    this.noise(0.4, 0.012, 2400);
  }

  death() {
    this.tone(220, 0.6, 'sawtooth', 0.06, 42);
    this.tone(95, 0.8, 'sine', 0.07, 34);
    this.noise(0.7, 0.08, 900);
  }

  portal() {
    [330, 440, 554, 660, 880, 1100].forEach((f, i) => this.tone(f, 0.7, 'sine', 0.04, null, i * 0.075));
    this.noise(0.9, 0.02, 3200);
  }

  unlockSfx() {
    [440, 660, 880, 1320].forEach((f, i) => this.tone(f, 0.35, 'triangle', 0.035, null, i * 0.09));
  }

  rewindStart() {
    if (!this.ready || !this.enabled) return;
    if (this.rewindNodes) this.rewindStop(true);
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const osc2 = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    osc.type = 'sawtooth';
    osc2.type = 'sine';
    osc.frequency.setValueAtTime(180, t);
    osc.frequency.exponentialRampToValueAtTime(72, t + 1.8);
    osc2.frequency.setValueAtTime(360, t);
    osc2.frequency.exponentialRampToValueAtTime(144, t + 1.8);
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(900, t);
    filter.frequency.linearRampToValueAtTime(260, t + 2);
    filter.Q.value = 5;
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(0.035, t + 0.12);
    osc.connect(filter);
    osc2.connect(filter);
    filter.connect(gain);
    gain.connect(this.sfxBus);
    gain.connect(this.reverb);
    osc.start(t); osc2.start(t);
    this.rewindNodes = { osc, osc2, gain };
    this.noise(1.2, 0.026, 2800, 0, 'bandpass');
  }

  rewindStop(instant = false) {
    if (!this.rewindNodes || !this.ctx) return;
    const { osc, osc2, gain } = this.rewindNodes;
    const t = this.ctx.currentTime;
    gain.gain.cancelScheduledValues(t);
    gain.gain.setValueAtTime(Math.max(0.0001, gain.gain.value), t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + (instant ? 0.01 : 0.18));
    try { osc.stop(t + 0.22); osc2.stop(t + 0.22); } catch { /* already stopped */ }
    this.rewindNodes = null;
    if (!instant) this.tone(160, 0.25, 'triangle', 0.045, 520);
  }

  rewindTick(progress) {
    if (!this.ready || !this.enabled || Math.random() > 0.28) return;
    this.tone(420 + progress * 380, 0.03, 'square', 0.008, null);
  }
}

/* ============================================================
   TIME REWIND — particle field
   ============================================================ */

const TAU = Math.PI * 2;

export class ParticleField {
  constructor() {
    this.items = [];
    this.max = 760;
  }

  add(p) {
    if (this.items.length >= this.max) this.items.shift();
    p.max = p.life = p.life ?? 0.5;
    p.age = 0;
    p.vx ??= 0; p.vy ??= 0; p.gravity ??= 0; p.drag ??= 0;
    p.size ??= 2; p.rot ??= 0; p.spin ??= 0; p.alpha ??= 1;
    p.type ??= 'dot'; p.color ??= '#57f2ff';
    this.items.push(p);
    return p;
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i--) {
      const p = this.items[i];
      p.age += dt;
      if (p.age >= p.life) { this.items.splice(i, 1); continue; }
      p.vy += p.gravity * dt;
      const damp = Math.max(0, 1 - p.drag * dt);
      p.vx *= damp; p.vy *= damp;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rot += p.spin * dt;
    }
  }

  clear() { this.items.length = 0; }

  draw(ctx) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const p of this.items) {
      const t = p.age / p.life;
      const fade = (1 - t) * p.alpha;
      if (fade <= 0.002) continue;
      ctx.globalAlpha = Math.min(1, fade);
      if (p.type === 'ring') {
        const r = p.size + (p.grow ?? 50) * easeOut(t);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = Math.max(0.6, (p.width ?? 1.5) * (1 - t));
        ctx.beginPath();
        ctx.arc(p.x, p.y, r, 0, TAU);
        ctx.stroke();
      } else if (p.type === 'line' || p.type === 'streak') {
        const len = p.len ?? 20;
        const speed = Math.hypot(p.vx, p.vy) || 1;
        const nx = p.vx / speed, ny = p.vy / speed;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = p.size;
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x - nx * len, p.y - ny * len);
        ctx.stroke();
      } else if (p.type === 'glyph') {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 1;
        ctx.strokeRect(-p.size / 2, -p.size / 2, p.size, p.size);
        ctx.restore();
      } else if (p.type === 'shard') {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.moveTo(0, -p.size);
        ctx.lineTo(p.size * .55, 0);
        ctx.lineTo(0, p.size);
        ctx.lineTo(-p.size * .55, 0);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      } else if (p.type === 'smoke') {
        ctx.globalCompositeOperation = 'source-over';
        const grad = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.size * (1 + t * 1.8));
        grad.addColorStop(0, p.color);
        grad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.globalAlpha = fade * 0.25;
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (1 + t * 1.8), 0, TAU);
        ctx.fill();
        ctx.globalCompositeOperation = 'lighter';
      } else {
        const s = p.size * (p.shrink === false ? 1 : (1 - t * 0.35));
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, Math.max(0.3, s), 0, TAU);
        ctx.fill();
        if (p.glow !== false && s > 1.1) {
          ctx.globalAlpha = fade * 0.16;
          ctx.beginPath();
          ctx.arc(p.x, p.y, s * 3.4, 0, TAU);
          ctx.fill();
        }
      }
    }
    ctx.restore();
  }

  /* ---------------- authored effects ---------------- */

  run(x, y, dir, color) {
    if (Math.random() > 0.55) return;
    this.add({
      x: x - dir * 8 + rnd(-4, 4), y: y - rnd(0, 3),
      vx: -dir * rnd(12, 55), vy: -rnd(4, 22),
      life: rnd(0.2, 0.5), size: rnd(.8, 2), color,
      gravity: -12, drag: 1.2
    });
  }

  jump(x, y, color) {
    for (let i = 0; i < 12; i++) {
      const a = Math.PI + rnd(-0.8, 0.8);
      this.add({ x: x + rnd(-10, 10), y, vx: Math.cos(a) * rnd(20, 100), vy: Math.sin(a) * rnd(20, 70), life: rnd(.25, .55), size: rnd(1, 2.4), color, gravity: 90, drag: 2 });
    }
    this.add({ type: 'ring', x, y: y - 2, size: 5, grow: 28, life: .35, color, width: 1.2 });
  }

  land(x, y, color) {
    for (let i = 0; i < 10; i++) {
      this.add({ x: x + rnd(-12, 12), y: y - 1, vx: rnd(-70, 70), vy: -rnd(6, 38), life: rnd(.18, .45), size: rnd(1, 2), color, gravity: 140, drag: 2.2 });
    }
    this.add({ type: 'ring', x, y: y - 1, size: 8, grow: 34, life: .3, color, width: 1 });
  }

  death(x, y, color, accent) {
    for (let i = 0; i < 38; i++) {
      const a = Math.random() * TAU;
      const s = rnd(40, 260);
      this.add({
        type: i % 4 === 0 ? 'shard' : 'dot',
        x, y: y - 24, vx: Math.cos(a) * s, vy: Math.sin(a) * s - 30,
        life: rnd(.4, 1.1), size: rnd(1.4, 3.6), color: i % 3 ? color : accent,
        gravity: 280, drag: 1.6, spin: rnd(-8, 8), rot: Math.random() * TAU
      });
    }
    this.add({ type: 'ring', x, y: y - 24, size: 10, grow: 130, life: .7, color: '#ff4f7b', width: 3 });
    this.add({ type: 'ring', x, y: y - 24, size: 2, grow: 80, life: .5, color: '#ffffff', width: 1 });
    for (let i = 0; i < 5; i++) this.add({ type: 'smoke', x: x + rnd(-15, 15), y: y - rnd(8, 40), vx: rnd(-20, 20), vy: -rnd(10, 40), life: rnd(.6, 1.4), size: rnd(12, 28), color: 'rgba(255,80,110,.5)', drag: 1 });
  }

  pickupCore(x, y) {
    for (let i = 0; i < 18; i++) {
      const a = Math.random() * TAU;
      this.add({ x, y, vx: Math.cos(a) * rnd(30, 130), vy: Math.sin(a) * rnd(30, 130) - 20, life: rnd(.35, .8), size: rnd(1, 2.6), color: i % 3 ? '#ffd36e' : '#ffffff', drag: 1.5, gravity: 40 });
    }
    this.add({ type: 'ring', x, y, size: 6, grow: 52, life: .5, color: '#ffd36e', width: 1.6 });
    this.add({ type: 'ring', x, y, size: 3, grow: 28, life: .35, color: '#fff2c4', width: 1 });
  }

  pickupEnergy(x, y) {
    for (let i = 0; i < 15; i++) {
      const a = Math.random() * TAU;
      this.add({ x, y, vx: Math.cos(a) * rnd(20, 110), vy: Math.sin(a) * rnd(20, 110), life: rnd(.3, .7), size: rnd(1, 2.2), color: i % 2 ? '#57f2ff' : '#b6fdff', drag: 1.5 });
    }
    this.add({ type: 'ring', x, y, size: 4, grow: 42, life: .45, color: '#57f2ff', width: 1.4 });
  }

  checkpoint(x, y) {
    for (let i = 0; i < 22; i++) {
      this.add({ type: 'glyph', x: x + rnd(-20, 20), y: y - rnd(0, 80), vx: rnd(-8, 8), vy: -rnd(20, 65), life: rnd(.6, 1.3), size: rnd(2, 4), color: i % 2 ? '#57f2ff' : '#d8fdff', drag: .5, spin: rnd(-4, 4) });
    }
    this.add({ type: 'ring', x, y: y - 15, size: 8, grow: 75, life: .7, color: '#57f2ff', width: 2 });
  }

  portal(x, y, color) {
    for (let i = 0; i < 4; i++) {
      const a = Math.random() * TAU;
      const r = rnd(18, 48);
      this.add({ x: x + Math.cos(a) * r * .55, y: y - 52 + Math.sin(a) * r, vx: Math.cos(a + 1.57) * rnd(10, 45), vy: Math.sin(a + 1.57) * rnd(10, 45), life: rnd(.4, .9), size: rnd(.7, 2), color, drag: .8 });
    }
  }

  rewindBurst(x, y, color) {
    for (let i = 0; i < 5; i++) {
      const a = Math.random() * TAU;
      const r = rnd(12, 38);
      this.add({ type: i % 3 === 1 ? 'glyph' : 'dot', x: x + Math.cos(a) * r, y: y - 24 + Math.sin(a) * r, vx: Math.cos(a) * 20, vy: Math.sin(a) * 20, life: rnd(.3, .7), size: rnd(1, 3), color, drag: 2, spin: rnd(-5, 5) });
    }
    if (Math.random() > .7) this.add({ type: 'ring', x, y: y - 22, size: 20, grow: 45, life: .4, color, width: 1 });
  }

  echoPulse(x, y, color) {
    for (let i = 0; i < 20; i++) {
      this.add({ type: 'glyph', x: x + rnd(-60, 60), y: y + rnd(-5, 5), vx: rnd(-15, 15), vy: -rnd(25, 80), life: rnd(.5, 1), size: rnd(1.5, 3.5), color, drag: .8, spin: rnd(-3, 3) });
    }
    this.add({ type: 'ring', x, y: y - 5, size: 20, grow: 100, life: .55, color, width: 1.2 });
  }

  enemyAlert(x, y) {
    for (let i = 0; i < 5; i++) this.add({ x: x + rnd(-8, 8), y: y + rnd(-8, 8), vx: rnd(-30, 30), vy: rnd(-50, -10), life: rnd(.2, .45), size: rnd(1, 2), color: '#ff4f7b', drag: 2 });
  }

  dust(x, y, color) {
    this.add({ x, y, vx: rnd(-12, 12), vy: rnd(-18, -5), life: rnd(.8, 1.7), size: rnd(.4, 1.2), color, drag: .2 });
  }
}

function rnd(a, b) { return a + Math.random() * (b - a); }
function easeOut(t) { return 1 - Math.pow(1 - t, 3); }

