/* ============================================================
   TIME REWIND — procedural skyline + parallax atmosphere
   ============================================================ */

const TAU = Math.PI * 2;

function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function hashString(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) h = Math.imul(h ^ str.charCodeAt(i), 16777619);
  return h >>> 0;
}

export class Background {
  constructor(level) {
    this.level = level;
    this.palette = level.palette;
    this.seed = hashString(level.id);
    const rand = rng(this.seed);
    this.stars = Array.from({ length: 150 }, () => ({
      x: rand() * 1540 - 130,
      y: rand() * 470,
      r: rand() * 1.4 + 0.3,
      a: rand() * .55 + .15,
      tw: rand() * TAU,
      speed: rand() * 1.5 + .4
    }));
    this.motes = Array.from({ length: 45 }, () => ({
      x: rand() * 1560 - 140,
      y: rand() * 690,
      r: rand() * 2.2 + .4,
      a: rand() * .22 + .04,
      speed: rand() * 10 + 3,
      drift: rand() * 12 - 6,
      phase: rand() * TAU
    }));
    this.layers = [
      this.makeCity(rand, 'far', -160, 1560, 46, 112, 450, 120, 0.15),
      this.makeCity(rand, 'mid', -160, 1560, 70, 160, 390, 180, 0.28),
      this.makeCity(rand, 'near', -160, 1560, 90, 210, 500, 220, 0.45)
    ];
    this.neon = Array.from({ length: 16 }, () => ({
      x: rand() * 1400 - 60,
      y: 440 + rand() * 170,
      w: rand() * 38 + 9,
      h: rand() * 3 + 1,
      color: rand() > .55 ? this.palette.accent : this.palette.accent2,
      phase: rand() * TAU
    }));
    this.rays = Array.from({ length: 5 }, (_, i) => ({
      x: 180 + i * 255 + rand() * 70,
      w: 80 + rand() * 160,
      a: rand() * .035 + .012,
      phase: rand() * TAU
    }));
  }

  makeCity(rand, layer, from, to, minW, maxW, minTop, heightRange, parallax) {
    const buildings = [];
    let x = from;
    while (x < to) {
      const w = minW + rand() * (maxW - minW);
      const top = minTop + rand() * heightRange;
      const body = {
        x, w, top,
        h: 760 - top,
        depth: rand(),
        antenna: rand() > .62 ? 10 + rand() * 42 : 0,
        roof: rand() > .55 ? Math.floor(rand() * 3) : 0,
        windows: [],
        signs: []
      };
      const cols = Math.max(1, Math.floor(w / 15));
      const rows = Math.max(2, Math.floor((720 - top) / 19));
      for (let c = 0; c < cols; c++) {
        for (let r = 0; r < rows; r++) {
          if (rand() > .68) continue;
          body.windows.push({
            x: 7 + c * (w - 12) / cols,
            y: 16 + r * 18,
            w: 2.5 + rand() * 2.4,
            h: 3 + rand() * 3,
            a: rand() * .55 + .15,
            color: rand() > .82 ? this.palette.accent2 : this.palette.window
          });
        }
      }
      if (rand() > .78) {
        body.signs.push({
          x: 5 + rand() * Math.max(1, w - 20),
          y: 28 + rand() * 70,
          h: 3 + rand() * 4,
          w: 10 + rand() * 17,
          color: rand() > .5 ? this.palette.accent : this.palette.accent2
        });
      }
      buildings.push(body);
      x += w + rand() * 10 + 2;
    }
    return { buildings, parallax, layer };
  }

  draw(ctx, camX, viewW, time, reduced = false) {
    const p = this.palette;
    const sky = ctx.createLinearGradient(0, 0, 0, 726);
    sky.addColorStop(0, p.skyTop);
    sky.addColorStop(0.48, p.skyMid);
    sky.addColorStop(0.82, p.skyBottom);
    sky.addColorStop(1, '#03050c');
    ctx.fillStyle = sky;
    ctx.fillRect(camX - 140, -20, viewW + 300, 770);

    // soft nebula blooms
    const neb = ctx.createRadialGradient(930 - camX * .06, 240, 10, 930 - camX * .06, 240, 480);
    neb.addColorStop(0, p.haze);
    neb.addColorStop(.52, p.haze.replace(/[\d.]+\)$/, '.035)'));
    neb.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = neb;
    ctx.fillRect(camX - 200, -60, viewW + 400, 800);

    // stars
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const s of this.stars) {
      const x = s.x + camX * .93;
      const a = s.a * (0.68 + Math.sin(time * s.speed + s.tw) * .32);
      ctx.globalAlpha = a;
      ctx.fillStyle = s.r > 1.15 ? p.accent : '#dbe7ff';
      ctx.beginPath();
      ctx.arc(x, s.y, s.r, 0, TAU);
      ctx.fill();
      if (s.r > 1.1) {
        ctx.globalAlpha = a * .23;
        ctx.beginPath();
        ctx.arc(x, s.y, s.r * 4.2, 0, TAU);
        ctx.fill();
      }
    }
    ctx.restore();

    this.drawPlanet(ctx, camX, time);

    // aurora ribbons
    if (!reduced) this.drawAurora(ctx, camX, viewW, time);

    // distant light shafts
    for (const r of this.rays) {
      const x = r.x + camX * .96;
      const g = ctx.createLinearGradient(x, 0, x + r.w, 700);
      g.addColorStop(0, `rgba(141,176,255,${r.a * (.7 + Math.sin(time * .3 + r.phase) * .3)})`);
      g.addColorStop(1, 'rgba(60,120,255,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x + r.w, 0);
      ctx.lineTo(x + r.w * 2.3, 700);
      ctx.lineTo(x + r.w * .4, 700);
      ctx.closePath();
      ctx.fill();
    }

    // layered city
    for (const layer of this.layers) this.drawLayer(ctx, layer, camX, time);

    // horizon glow + fog
    const horizon = ctx.createLinearGradient(0, 480, 0, 720);
    horizon.addColorStop(0, 'rgba(0,0,0,0)');
    horizon.addColorStop(.55, p.haze);
    horizon.addColorStop(1, 'rgba(3,5,12,.84)');
    ctx.fillStyle = horizon;
    ctx.fillRect(camX - 80, 440, viewW + 160, 300);

    // neon signs
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const n of this.neon) {
      const x = n.x + camX * .55;
      ctx.globalAlpha = .35 + Math.sin(time * 1.2 + n.phase) * .18;
      ctx.fillStyle = n.color;
      ctx.fillRect(x, n.y, n.w, n.h);
      ctx.globalAlpha = .09;
      ctx.fillRect(x - 3, n.y - 4, n.w + 6, n.h + 8);
    }
    ctx.restore();

    // floating dust motes
    ctx.save();
    for (const m of this.motes) {
      const x = m.x + camX * .9 + Math.sin(time * .18 + m.phase) * 13;
      const y = (m.y - time * m.speed * .25 + 720) % 740;
      ctx.globalAlpha = m.a * (.6 + Math.sin(time + m.phase) * .4);
      ctx.fillStyle = p.accent;
      ctx.beginPath();
      ctx.arc(x, y, m.r, 0, TAU);
      ctx.fill();
    }
    ctx.restore();

    // foreground mist
    const mist = ctx.createLinearGradient(0, 590, 0, 740);
    mist.addColorStop(0, 'rgba(4,8,20,0)');
    mist.addColorStop(.7, 'rgba(4,8,20,.34)');
    mist.addColorStop(1, 'rgba(3,5,12,.72)');
    ctx.fillStyle = mist;
    ctx.fillRect(camX - 100, 580, viewW + 200, 170);
  }

  drawPlanet(ctx, camX, time) {
    const p = this.palette;
    const px = 1010 + camX * .93;
    const py = 146;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const halo = ctx.createRadialGradient(px, py, 12, px, py, 160);
    halo.addColorStop(0, p.accent + '30');
    halo.addColorStop(.45, p.haze);
    halo.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = halo;
    ctx.beginPath(); ctx.arc(px, py, 160, 0, TAU); ctx.fill();
    ctx.restore();

    ctx.save();
    const grad = ctx.createLinearGradient(px - 70, py - 70, px + 80, py + 80);
    grad.addColorStop(0, '#d9edff');
    grad.addColorStop(.22, p.accent);
    grad.addColorStop(.6, '#3142a8');
    grad.addColorStop(1, '#0d1135');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(px, py, 76, 0, TAU);
    ctx.fill();
    ctx.globalAlpha = .28;
    ctx.fillStyle = p.accent2;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.ellipse(px - 10, py + (i - 1) * 25, 70, 13, -.2, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = .42;
    ctx.strokeStyle = p.accent;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.ellipse(px, py, 128, 25, -.33, 0, TAU);
    ctx.stroke();
    ctx.globalAlpha = .16;
    ctx.beginPath();
    ctx.ellipse(px, py, 154, 35, -.33, 0, TAU);
    ctx.stroke();
    ctx.restore();
  }

  drawAurora(ctx, camX, viewW, time) {
    const p = this.palette;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let band = 0; band < 3; band++) {
      const y = 150 + band * 78 + Math.sin(time * .22 + band) * 19;
      const g = ctx.createLinearGradient(camX, y - 70, camX + viewW, y + 80);
      g.addColorStop(0, 'rgba(0,0,0,0)');
      g.addColorStop(.3, p.accent + '10');
      g.addColorStop(.55, p.accent2 + '12');
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.strokeStyle = g;
      ctx.lineWidth = 36 + band * 13;
      ctx.globalAlpha = .17;
      ctx.beginPath();
      for (let x = camX - 100; x <= camX + viewW + 100; x += 38) {
        const yy = y + Math.sin(x * .0032 + time * .34 + band * 1.7) * 42 + Math.sin(x * .0011 - time * .18) * 25;
        if (x === camX - 100) ctx.moveTo(x, yy); else ctx.lineTo(x, yy);
      }
      ctx.stroke();
    }
    ctx.restore();
  }

  drawLayer(ctx, layer, camX, time) {
    const p = this.palette;
    const colors = { far: p.far, mid: p.mid, near: p.near };
    const offset = camX * (1 - layer.parallax);
    ctx.save();
    ctx.translate(offset, 0);
    for (const b of layer.buildings) {
      ctx.fillStyle = colors[layer.layer];
      ctx.fillRect(b.x, b.top, b.w, b.h);
      ctx.fillStyle = layer.layer === 'far' ? 'rgba(160,190,255,.055)' : 'rgba(190,215,255,.09)';
      ctx.fillRect(b.x, b.top, b.w, 1);
      ctx.fillStyle = 'rgba(255,255,255,.035)';
      ctx.fillRect(b.x + 2, b.top + 2, 1, b.h - 2);
      if (b.antenna) {
        ctx.fillStyle = colors[layer.layer];
        ctx.fillRect(b.x + b.w * .5, b.top - b.antenna, 1.5, b.antenna);
        ctx.fillStyle = p.accent2;
        ctx.globalAlpha = .45 + Math.sin(time * 2 + b.x) * .22;
        ctx.fillRect(b.x + b.w * .5 - 1, b.top - b.antenna, 3, 2);
        ctx.globalAlpha = 1;
      }
      if (b.roof === 1) {
        ctx.fillStyle = colors[layer.layer];
        ctx.fillRect(b.x + b.w * .18, b.top - 13, b.w * .28, 13);
      } else if (b.roof === 2) {
        ctx.fillStyle = colors[layer.layer];
        ctx.fillRect(b.x + b.w * .55, b.top - 20, 2, 20);
      }
      for (const w of b.windows) {
        ctx.globalAlpha = w.a * (layer.layer === 'near' ? .72 : .5);
        ctx.fillStyle = w.color;
        ctx.fillRect(b.x + w.x, b.top + w.y, w.w, w.h);
      }
      ctx.globalAlpha = 1;
      for (const s of b.signs) {
        ctx.globalAlpha = .35 + Math.sin(time * .8 + s.y) * .15;
        ctx.fillStyle = s.color;
        ctx.fillRect(b.x + s.x, b.top + s.y, s.w, s.h);
        ctx.globalAlpha = 1;
      }
    }
    ctx.restore();
  }

  /* Menu-only monument: a vast broken chrono ring on the horizon. */
  drawMenuMonument(ctx, time) {
    const cx = 960;
    const cy = 356;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const halo = ctx.createRadialGradient(cx, cy, 20, cx, cy, 340);
    halo.addColorStop(0, 'rgba(87,242,255,.10)');
    halo.addColorStop(.55, 'rgba(109,96,255,.045)');
    halo.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = halo;
    ctx.beginPath(); ctx.arc(cx, cy, 340, 0, TAU); ctx.fill();
    for (let ring = 0; ring < 4; ring++) {
      ctx.strokeStyle = ring % 2 ? 'rgba(255,95,205,.16)' : 'rgba(87,242,255,.2)';
      ctx.lineWidth = ring === 0 ? 1.5 : 1;
      ctx.setLineDash(ring === 1 ? [2, 9] : ring === 2 ? [34, 16] : []);
      ctx.beginPath();
      ctx.arc(cx, cy, 180 + ring * 48, time * (.03 + ring * .012), time * (.03 + ring * .012) + TAU * (.68 + ring * .04));
      ctx.stroke();
    }
    ctx.setLineDash([]);
    // broken arch shards
    for (let i = 0; i < 22; i++) {
      const a = i / 22 * TAU + time * .014;
      const r = 310 + Math.sin(i * 2.1) * 30;
      const x = cx + Math.cos(a) * r;
      const y = cy + Math.sin(a) * r * .58;
      ctx.globalAlpha = .12 + (i % 4) * .025;
      ctx.fillStyle = i % 3 ? '#8ddfff' : '#ff79d4';
      ctx.fillRect(x, y, 2, 9);
    }
    ctx.restore();
  }
}

/* ============================================================
   TIME REWIND — vector draw routines
   ============================================================ */

const TAU = Math.PI * 2;

export function rgba(hex, a) {
  const h = hex.replace('#', '');
  const full = h.length === 3 ? h.split('').map(c => c + c).join('') : h;
  const n = parseInt(full, 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
}

export function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.lineTo(x + w - rr, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
  ctx.lineTo(x + w, y + h - rr);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
  ctx.lineTo(x + rr, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
  ctx.lineTo(x, y + rr);
  ctx.quadraticCurveTo(x, y, x + rr, y);
  ctx.closePath();
}

export function glowCircle(ctx, x, y, r, color, alpha = 1) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, rgba(color, .55 * alpha));
  g.addColorStop(.38, rgba(color, .17 * alpha));
  g.addColorStop(1, rgba(color, 0));
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  ctx.fill();
}

export function drawPlatform(ctx, p, time, palette, echoActive, reduced) {
  if (p.kind === 'crumble' && p.state === 2) {
    return;
  }
  const active = p.kind !== 'phase' || p.phaseActive;
  const echo = p.kind === 'echo';
  const echoOn = echoActive;
  let alpha = 1;
  if (p.kind === 'phase') alpha = active ? 1 : 0.17;
  if (echo) alpha = echoOn ? 1 : 0.19;
  const x = p.curX + (p.kind === 'crumble' && p.state === 1 ? Math.sin(time * 68) * 2.2 : 0);
  const y = p.curY + (p.kind === 'crumble' ? p.fall || 0 : 0);
  const w = p.w, h = p.h;
  const accent = p.kind === 'crumble' ? '#ffb15f' : p.kind === 'phase' ? '#a68cff' : echo ? '#ffd36e' : palette.accent;
  ctx.save();
  ctx.globalAlpha = alpha;

  // underglow / support
  if (w < 300) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createLinearGradient(x, y + h, x, y + h + 42);
    g.addColorStop(0, rgba(accent, echoOn ? .18 : .08));
    g.addColorStop(1, rgba(accent, 0));
    ctx.fillStyle = g;
    ctx.fillRect(x + w * .12, y + h, w * .76, 42);
    ctx.restore();
  }

  // body
  const grad = ctx.createLinearGradient(x, y, x, y + Math.min(h, 120));
  grad.addColorStop(0, p.kind === 'crumble' ? '#251d2c' : echo ? '#242039' : '#111a35');
  grad.addColorStop(.2, '#0a1024');
  grad.addColorStop(1, '#060a17');
  ctx.fillStyle = grad;
  roundRect(ctx, x, y, w, h, h > 40 ? 5 : 3);
  ctx.fill();

  // inner face etching
  ctx.strokeStyle = rgba(accent, .11);
  ctx.lineWidth = 1;
  if (w > 40) {
    ctx.beginPath();
    ctx.moveTo(x + 8, y + Math.min(h - 4, 18));
    ctx.lineTo(x + w - 8, y + Math.min(h - 4, 18));
    ctx.stroke();
  }
  if (h > 50) {
    for (let i = 1; i < Math.min(4, Math.floor(w / 90)); i++) {
      ctx.beginPath();
      ctx.moveTo(x + w * i / 4, y + 20);
      ctx.lineTo(x + w * i / 4, y + h - 8);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.arc(x + w - 17, y + 17, 3, 0, TAU);
    ctx.strokeStyle = rgba(accent, .25);
    ctx.stroke();
  }

  // top edge
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = rgba(accent, echoOn || active ? .9 : .3);
  ctx.fillRect(x + 2, y, w - 4, 1.6);
  ctx.fillStyle = rgba(accent, echoOn || active ? .17 : .05);
  ctx.fillRect(x + 2, y - 3, w - 4, 7);
  ctx.restore();

  // corner brackets
  ctx.strokeStyle = rgba(accent, .65);
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x, y + 12); ctx.lineTo(x, y); ctx.lineTo(x + 12, y);
  ctx.moveTo(x + w - 12, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + 12);
  ctx.stroke();

  if (p.kind === 'crumble') {
    ctx.strokeStyle = rgba('#ffb15f', .35);
    ctx.lineWidth = .8;
    ctx.beginPath();
    ctx.moveTo(x + w * .22, y + 2);
    ctx.lineTo(x + w * .32, y + 8);
    ctx.lineTo(x + w * .27, y + h * .6);
    ctx.moveTo(x + w * .62, y);
    ctx.lineTo(x + w * .56, y + 7);
    ctx.lineTo(x + w * .7, y + h * .45);
    ctx.moveTo(x + w * .76, y + 2);
    ctx.lineTo(x + w * .82, y + h * .7);
    ctx.stroke();
  }

  if (p.kind === 'phase') {
    ctx.setLineDash([5, 5]);
    ctx.strokeStyle = rgba(active ? '#c3b5ff' : '#8a79c9', active ? .48 : .34);
    ctx.lineWidth = 1;
    roundRect(ctx, x + 3, y + 3, w - 6, h - 6, 2);
    ctx.stroke();
    ctx.setLineDash([]);
    if (!active) {
      ctx.fillStyle = rgba('#beaaff', .16);
      for (let i = 0; i < w; i += 19) {
        const hh = 2 + (Math.sin(time * 2 + i) + 1) * 1.5;
        ctx.fillRect(x + i, y + h / 2 - hh / 2, 10, hh);
      }
    }
  }

  if (echo) {
    ctx.setLineDash(echoOn ? [] : [3, 6]);
    ctx.strokeStyle = rgba('#ffd36e', echoOn ? .5 : .28);
    ctx.lineWidth = 1;
    roundRect(ctx, x + 2, y + 2, w - 4, h - 4, 2);
    ctx.stroke();
    ctx.setLineDash([]);
    if (!echoOn) {
      ctx.fillStyle = rgba('#ffd36e', .1);
      ctx.font = '7px "DejaVu Sans Mono", monospace';
      ctx.textAlign = 'center';
      ctx.fillText('ECHO', x + w / 2, y + h / 2 + 2.5);
    }
  }

  // moving thrusters
  if (p.move) {
    const bob = Math.sin(time * 5 + p.id) * 1.5;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 3; i++) {
      const tx = x + w * (.25 + i * .25);
      const tg = ctx.createRadialGradient(tx, y + h + 3, 0, tx, y + h + 3, 13 + bob);
      tg.addColorStop(0, rgba(accent, .55));
      tg.addColorStop(1, rgba(accent, 0));
      ctx.fillStyle = tg;
      ctx.beginPath(); ctx.arc(tx, y + h + 3, 13 + bob, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }

  // faint circuit scratches
  ctx.globalAlpha = alpha * .25;
  ctx.strokeStyle = rgba(accent, .5);
  for (let i = 0; i < Math.min(3, Math.floor(w / 55)); i++) {
    const sx = x + 16 + i * 55;
    ctx.beginPath();
    ctx.moveTo(sx, y + Math.min(h - 5, 24));
    ctx.lineTo(sx + 10, y + Math.min(h - 5, 24));
    ctx.lineTo(sx + 14, y + Math.min(h - 5, 18));
    ctx.stroke();
  }
  ctx.restore();
}

export function drawLaser(ctx, h, time, palette) {
  const x = h.x, y = h.y, w = h.w, hh = h.h;
  const cyc = ((time + (h.phase || 0)) % h.period) / h.period;
  const active = cyc < h.duty;
  const warning = !active && cyc > .86;
  const vertical = hh > w;
  const pulse = .72 + Math.sin(time * 22) * .28;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  // emitters
  const er = 5;
  const pts = vertical ? [[x + w / 2, y], [x + w / 2, y + hh]] : [[x, y + hh / 2], [x + w, y + hh / 2]];
  for (const [ex, ey] of pts) {
    glowCircle(ctx, ex, ey, 19, active ? '#ff4f7b' : '#ff9c7b', active ? .65 : .26);
    ctx.fillStyle = active ? '#ffd9e2' : '#8b7086';
    ctx.beginPath(); ctx.arc(ex, ey, 3.6, 0, TAU); ctx.fill();
    ctx.strokeStyle = rgba('#ff4f7b', active ? .7 : .25);
    ctx.beginPath(); ctx.arc(ex, ey, 7.5, 0, TAU); ctx.stroke();
  }
  if (active) {
    const g = vertical
      ? ctx.createLinearGradient(x, y, x + w, y)
      : ctx.createLinearGradient(x, y, x, y + hh);
    g.addColorStop(0, 'rgba(255,79,123,.12)');
    g.addColorStop(.5, 'rgba(255,79,123,.5)');
    g.addColorStop(1, 'rgba(255,79,123,.12)');
    ctx.fillStyle = g;
    ctx.fillRect(x - 5, y, w + 10, hh);
    ctx.fillStyle = rgba('#ff4f7b', .24 * pulse);
    if (vertical) ctx.fillRect(x - 14, y, w + 28, hh);
    else ctx.fillRect(x, y - 14, w, hh + 28);
    ctx.fillStyle = '#fff3f5';
    if (vertical) ctx.fillRect(x + w / 2 - .9, y, 1.8, hh);
    else ctx.fillRect(x, y + hh / 2 - .9, w, 1.8);
    // travelling energy ticks
    ctx.fillStyle = rgba('#ffd9e2', .75);
    const t = (time * 150) % 60;
    if (vertical) {
      ctx.fillRect(x + w / 2 - 1.3, y + t, 2.6, 11);
      ctx.fillRect(x + w / 2 - 1.3, y + hh - t, 2.6, 8);
    } else {
      ctx.fillRect(x + t, y + hh / 2 - 1.3, 11, 2.6);
      ctx.fillRect(x + w - t, y + hh / 2 - 1.3, 8, 2.6);
    }
  } else {
    ctx.setLineDash([3, 7]);
    ctx.strokeStyle = rgba('#ff8c9f', warning ? .6 : .18);
    ctx.lineWidth = 1;
    ctx.beginPath();
    if (vertical) { ctx.moveTo(x + w / 2, y); ctx.lineTo(x + w / 2, y + hh); }
    else { ctx.moveTo(x, y + hh / 2); ctx.lineTo(x + w, y + hh / 2); }
    ctx.stroke();
    ctx.setLineDash([]);
    if (warning) {
      ctx.globalAlpha = .3 + Math.sin(time * 30) * .25;
      ctx.fillStyle = '#ff9caf';
      if (vertical) ctx.fillRect(x - 1, y, w + 2, hh);
      else ctx.fillRect(x, y - 1, w, hh + 2);
    }
  }
  ctx.restore();
}

export function drawSaw(ctx, s, time, palette) {
  const cyc = ((time + (s.phase || 0)) % s.period) / s.period;
  const e = .5 - .5 * Math.cos(cyc * TAU);
  const x = s.x + (s.moveX || 0) * e;
  const y = s.y + (s.moveY || 0) * e;
  const r = s.r || 18;
  ctx.save();
  if (s.moveX || s.moveY) {
    ctx.strokeStyle = rgba('#ffb15f', .1);
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 8]);
    ctx.beginPath(); ctx.moveTo(s.x, s.y); ctx.lineTo(s.x + (s.moveX || 0), s.y + (s.moveY || 0)); ctx.stroke();
    ctx.setLineDash([]);
  }
  ctx.globalCompositeOperation = 'lighter';
  glowCircle(ctx, x, y, r * 2.2, '#ff9e57', .25);
  ctx.restore();

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(time * 5.8 + (s.phase || 0) * 8);
  ctx.fillStyle = '#2b2331';
  ctx.beginPath();
  for (let i = 0; i < 12; i++) {
    const a = i / 12 * TAU;
    const rr = r + (i % 2 ? 4.5 : 0);
    const ax = Math.cos(a) * rr, ay = Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(ax, ay); else ctx.lineTo(ax, ay);
  }
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = rgba('#ffb15f', .85);
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = '#120e17';
  ctx.beginPath(); ctx.arc(0, 0, r - 4, 0, TAU); ctx.fill();
  ctx.strokeStyle = rgba('#ffb15f', .25);
  ctx.beginPath(); ctx.arc(0, 0, r - 5, 0, TAU); ctx.stroke();
  ctx.fillStyle = '#ffb15f';
  ctx.beginPath(); ctx.arc(0, 0, 2.4, 0, TAU); ctx.fill();
  ctx.restore();
}

export function drawCore(ctx, c, time, palette) {
  if (c.collected) return;
  const bob = Math.sin(time * 2.3 + c.x * .02) * 4;
  const x = c.x, y = c.y + bob;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glowCircle(ctx, x, y, 29, '#ffd36e', .58);
  ctx.translate(x, y);
  ctx.rotate(time * 1.4);
  ctx.fillStyle = '#ffe8a6';
  ctx.beginPath();
  ctx.moveTo(0, -9); ctx.lineTo(7, 0); ctx.lineTo(0, 9); ctx.lineTo(-7, 0); ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#7a4c10';
  ctx.beginPath();
  ctx.moveTo(0, -4.4); ctx.lineTo(3.5, 0); ctx.lineTo(0, 4.4); ctx.lineTo(-3.5, 0); ctx.closePath();
  ctx.fill();
  ctx.rotate(-time * 1.4);
  ctx.strokeStyle = rgba('#ffd36e', .42);
  ctx.lineWidth = .9;
  ctx.beginPath();
  ctx.ellipse(0, 0, 15, 5, time * .8, 0, TAU);
  ctx.stroke();
  ctx.restore();
}

export function drawEnergy(ctx, e, time) {
  if (e.collected) return;
  const bob = Math.sin(time * 2.8 + e.x * .03) * 3;
  const x = e.x, y = e.y + bob;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glowCircle(ctx, x, y, 24, '#57f2ff', .42);
  ctx.translate(x, y);
  ctx.strokeStyle = rgba('#d7fdff', .9);
  ctx.lineWidth = 1.2;
  ctx.fillStyle = rgba('#0d3142', .8);
  ctx.beginPath();
  for (let i = 0; i < 6; i++) {
    const a = i / 6 * TAU - Math.PI / 2;
    const px = Math.cos(a) * 9, py = Math.sin(a) * 11;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill(); ctx.stroke();
  ctx.strokeStyle = '#a8fbff';
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.moveTo(0, -6); ctx.lineTo(-3, 1); ctx.lineTo(1, 1); ctx.lineTo(-1, 7); ctx.lineTo(4, -1); ctx.lineTo(0, -1); ctx.closePath();
  ctx.stroke();
  ctx.restore();
}

export function drawCheckpoint(ctx, c, time, palette, active) {
  const x = c.x, y = c.y;
  ctx.save();
  if (active) {
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createLinearGradient(x, y - 120, x, y);
    g.addColorStop(0, rgba('#57f2ff', 0));
    g.addColorStop(.65, rgba('#57f2ff', .09));
    g.addColorStop(1, rgba('#57f2ff', .22));
    ctx.fillStyle = g;
    ctx.fillRect(x - 10, y - 120, 20, 120);
    ctx.strokeStyle = rgba('#57f2ff', .28);
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let i = 0; i < 2; i++) {
      ctx.moveTo(x - 14, y - 14 - i * 28 - (time * 18 % 28));
      ctx.lineTo(x + 14, y - 14 - i * 28 - (time * 18 % 28));
    }
    ctx.stroke();
    ctx.restore();
  }
  ctx.save();
  ctx.fillStyle = '#060c19';
  ctx.strokeStyle = active ? rgba('#57f2ff', .8) : 'rgba(134,157,201,.35)';
  ctx.lineWidth = 1;
  roundRect(ctx, x - 25, y - 4, 50, 5, 2);
  ctx.fill(); ctx.stroke();
  ctx.fillStyle = active ? '#57f2ff' : '#4c5978';
  ctx.fillRect(x - 1, y - 17, 2, 13);
  ctx.beginPath(); ctx.arc(x, y - 19, 3, 0, TAU); ctx.fill();
  ctx.restore();
}

export function drawPortal(ctx, x, y, time, palette) {
  const bob = Math.sin(time * 1.6) * 2;
  ctx.save();
  ctx.translate(x, y + bob);
  // base
  ctx.fillStyle = 'rgba(5,10,22,.9)';
  ctx.strokeStyle = rgba(palette.accent, .55);
  ctx.beginPath();
  ctx.ellipse(0, 0, 42, 8, 0, 0, TAU);
  ctx.fill(); ctx.stroke();
  ctx.globalCompositeOperation = 'lighter';
  glowCircle(ctx, 0, -55, 80, palette.accent, .6);
  const g = ctx.createRadialGradient(0, -55, 2, 0, -55, 33);
  g.addColorStop(0, 'rgba(255,255,255,.95)');
  g.addColorStop(.22, rgba(palette.accent, .75));
  g.addColorStop(.6, rgba(palette.accent2, .18));
  g.addColorStop(1, rgba(palette.accent, 0));
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.ellipse(0, -55, 27, 46, 0, 0, TAU); ctx.fill();
  for (let i = 0; i < 3; i++) {
    ctx.strokeStyle = rgba(i === 1 ? palette.accent2 : palette.accent, .5 - i * .11);
    ctx.lineWidth = 1.1;
    ctx.beginPath();
    ctx.ellipse(0, -55, 31 + i * 7, 52 + i * 9, time * .3 + i * .6, 0, TAU);
    ctx.stroke();
  }
  ctx.strokeStyle = rgba('#ffffff', .72);
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.ellipse(0, -55, 24, 43, -time * .4, .3, 2.5);
  ctx.stroke();
  ctx.restore();
  // exit label
  ctx.save();
  ctx.globalAlpha = .55;
  ctx.fillStyle = rgba(palette.accent, .85);
  ctx.font = '700 8px "DejaVu Sans Mono", monospace';
  ctx.textAlign = 'center';
  ctx.letterSpacing = '2px';
  ctx.fillText('EXIT', x, y - 116);
  ctx.restore();
}

export function drawProjectile(ctx, p, time) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glowCircle(ctx, p.x, p.y, 17, '#ff5f7e', .55);
  ctx.strokeStyle = rgba('#ff8ba4', .35);
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(p.x, p.y);
  ctx.lineTo(p.x - p.vx * .045, p.y - p.vy * .045);
  ctx.stroke();
  ctx.fillStyle = '#fff1f5';
  ctx.beginPath(); ctx.arc(p.x, p.y, 3.2, 0, TAU); ctx.fill();
  ctx.restore();
}

export function drawSentinel(ctx, e, time, palette) {
  const x = e.x, y = e.y;
  const alert = e.state === 'chase';
  const walk = e.step || 0;
  ctx.save();
  // shadow
  ctx.fillStyle = 'rgba(0,0,0,.35)';
  ctx.beginPath(); ctx.ellipse(x, y, 22, 5, 0, 0, TAU); ctx.fill();

  // legs
  ctx.strokeStyle = alert ? 'rgba(255,91,116,.8)' : 'rgba(146,166,205,.5)';
  ctx.lineWidth = 2;
  for (let i = 0; i < 3; i++) {
    const side = i - 1;
    const swing = Math.sin(walk + i * 2.2) * 4;
    ctx.beginPath();
    ctx.moveTo(x + side * 8, y - 18);
    ctx.lineTo(x + side * 12 + swing, y - 8);
    ctx.lineTo(x + side * 16 + swing, y);
    ctx.stroke();
  }
  // body
  const g = ctx.createLinearGradient(x, y - 36, x, y - 6);
  g.addColorStop(0, alert ? '#3d1a2a' : '#1a223c');
  g.addColorStop(1, '#090d1c');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(x, y - 22, 16, 13, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = alert ? 'rgba(255,79,123,.8)' : 'rgba(126,154,211,.4)';
  ctx.stroke();
  // visor
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glowCircle(ctx, x + (alert ? e.dir * 2 : 0), y - 24, 14, alert ? '#ff4f7b' : '#ffb15f', .55);
  ctx.fillStyle = alert ? '#ff7d96' : '#ffbe6b';
  ctx.beginPath();
  ctx.ellipse(x + e.dir * 2, y - 24, 5, 2.2, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
  // antenna
  ctx.strokeStyle = 'rgba(143,172,227,.5)';
  ctx.beginPath(); ctx.moveTo(x, y - 34); ctx.lineTo(x, y - 42); ctx.stroke();
  ctx.fillStyle = alert ? '#ff4f7b' : '#6880ad';
  ctx.beginPath(); ctx.arc(x, y - 44, 2, 0, TAU); ctx.fill();
  if (alert) {
    ctx.globalAlpha = .45 + Math.sin(time * 8) * .25;
    ctx.strokeStyle = '#ff4f7b';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(x, y - 24, 23 + Math.sin(time * 4) * 3, 0, TAU); ctx.stroke();
  }
  ctx.restore();
}

export function drawDrone(ctx, e, time, palette) {
  const x = e.x, y = e.y + Math.sin(time * 2 + e.phase) * (e.alert ? 1 : 5);
  const alert = e.alert;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glowCircle(ctx, x, y + 6, 32, alert ? '#ff4f7b' : '#5fc6ff', .2);
  ctx.restore();

  // rotors
  ctx.save();
  ctx.translate(x, y);
  ctx.strokeStyle = 'rgba(157,184,238,.42)';
  ctx.lineWidth = 1;
  const spin = time * 18;
  for (const side of [-1, 1]) {
    ctx.save();
    ctx.translate(side * 16, -4);
    ctx.rotate(spin * side);
    ctx.beginPath(); ctx.moveTo(-7, 0); ctx.lineTo(7, 0); ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, 2, 0, TAU); ctx.stroke();
    ctx.restore();
  }
  // wings
  ctx.fillStyle = 'rgba(18,28,52,.9)';
  ctx.strokeStyle = alert ? 'rgba(255,79,123,.4)' : 'rgba(116,166,240,.35)';
  ctx.beginPath();
  ctx.moveTo(-21, -4); ctx.lineTo(-9, 0); ctx.lineTo(-9, 7); ctx.lineTo(-23, 4); ctx.closePath();
  ctx.moveTo(21, -4); ctx.lineTo(9, 0); ctx.lineTo(9, 7); ctx.lineTo(23, 4); ctx.closePath();
  ctx.fill(); ctx.stroke();
  // core diamond
  ctx.rotate(Math.PI / 4);
  const g = ctx.createLinearGradient(-8, -8, 8, 8);
  g.addColorStop(0, alert ? '#5d162a' : '#142846');
  g.addColorStop(1, '#070b17');
  ctx.fillStyle = g;
  ctx.fillRect(-9, -9, 18, 18);
  ctx.strokeStyle = alert ? 'rgba(255,79,123,.85)' : 'rgba(106,211,255,.55)';
  ctx.strokeRect(-9, -9, 18, 18);
  ctx.rotate(-Math.PI / 4);
  // eye
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glowCircle(ctx, 0, 0, 13, alert ? '#ff4f7b' : '#6ed5ff', .7);
  ctx.fillStyle = alert ? '#ff8fa4' : '#b7f4ff';
  ctx.beginPath(); ctx.arc(0, 0, 2.6, 0, TAU); ctx.fill();
  ctx.restore();
  if (alert) {
    ctx.strokeStyle = 'rgba(255,79,123,.32)';
    ctx.setLineDash([2, 5]);
    ctx.beginPath(); ctx.arc(0, 0, 18 + Math.sin(time * 5) * 2, 0, TAU); ctx.stroke();
    ctx.setLineDash([]);
  }
  ctx.restore();
}

export function drawPlayer(ctx, player, time, palette, options = {}) {
  const { x, y, vx, vy, facing, runPhase, onGround, squash, invuln } = player;
  const dir = facing || 1;
  const moving = Math.abs(vx) > 22;
  const air = !onGround;
  const body = options.ghost ? 'rgba(87,242,255,.35)' : '#eaf5ff';
  const suit = options.ghost ? 'rgba(87,242,255,.23)' : '#273d63';
  const accent = options.ghost ? 'rgba(87,242,255,.4)' : palette.accent;
  if (invuln > 0 && !options.ghost && Math.floor(time * 22) % 2 === 0) ctx.globalAlpha = .55;
  ctx.save();
  // shadow
  if (!options.ghost) {
    ctx.fillStyle = 'rgba(0,0,0,.4)';
    ctx.beginPath(); ctx.ellipse(x, y + 1, 17, 4, 0, 0, TAU); ctx.fill();
  }
  // speed trail
  if (moving && !air && !options.ghost) {
    ctx.strokeStyle = rgba(accent, .18);
    ctx.lineWidth = 1;
    for (let i = 0; i < 2; i++) {
      ctx.beginPath();
      ctx.moveTo(x - dir * (8 + i * 6), y - 13 + i * 7);
      ctx.lineTo(x - dir * (22 + i * 9), y - 13 + i * 7);
      ctx.stroke();
    }
  }
  ctx.translate(x, y);
  ctx.scale(dir, squash || 1);
  const swing = moving ? Math.sin(runPhase) : 0;
  const swing2 = moving ? Math.sin(runPhase + Math.PI) : 0;
  const legLift = air ? 6 : 0;
  // legs
  ctx.lineCap = 'round';
  ctx.strokeStyle = suit;
  ctx.lineWidth = 5.4;
  ctx.beginPath();
  if (air) {
    ctx.moveTo(-4, -20); ctx.lineTo(-8, -9); ctx.lineTo(-10, -legLift);
    ctx.moveTo(5, -20); ctx.lineTo(8, -10); ctx.lineTo(10, -4);
  } else {
    ctx.moveTo(-4, -20); ctx.lineTo(-5 + swing * 7, -10); ctx.lineTo(-8 + swing * 11, 0);
    ctx.moveTo(5, -20); ctx.lineTo(6 + swing2 * 7, -10); ctx.lineTo(9 + swing2 * 11, 0);
  }
  ctx.stroke();
  // boots / knees
  ctx.strokeStyle = accent;
  ctx.lineWidth = 2;
  ctx.beginPath();
  if (air) {
    ctx.moveTo(-11, -legLift); ctx.lineTo(-5, -legLift);
    ctx.moveTo(8, -4); ctx.lineTo(13, -4);
  } else {
    ctx.moveTo(-10 + swing * 11, 0); ctx.lineTo(-3 + swing * 11, 0);
    ctx.moveTo(7 + swing2 * 11, 0); ctx.lineTo(13 + swing2 * 11, 0);
  }
  ctx.stroke();
  // scarf / back ribbon
  ctx.save();
  ctx.strokeStyle = options.ghost ? 'rgba(87,242,255,.3)' : 'rgba(87,242,255,.75)';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(-2, -41);
  const wind = -dir * (14 + Math.abs(vx) * .045);
  ctx.quadraticCurveTo(wind * .5, -39 + Math.sin(time * 5) * 2, wind, -32 + Math.sin(time * 4.4) * 4);
  ctx.stroke();
  ctx.restore();
  // torso
  const torso = ctx.createLinearGradient(0, -47, 0, -16);
  torso.addColorStop(0, body);
  torso.addColorStop(.38, options.ghost ? 'rgba(87,242,255,.28)' : '#9bb3d4');
  torso.addColorStop(1, suit);
  ctx.fillStyle = torso;
  ctx.beginPath();
  ctx.moveTo(-8, -44);
  ctx.quadraticCurveTo(-12, -34, -7, -18);
  ctx.lineTo(7, -18);
  ctx.quadraticCurveTo(12, -34, 8, -44);
  ctx.quadraticCurveTo(0, -49, -8, -44);
  ctx.closePath();
  ctx.fill();
  // chest core
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glowCircle(ctx, 2, -33, 8, accent, .65);
  ctx.fillStyle = '#eaffff';
  ctx.beginPath(); ctx.arc(2, -33, 2.6, 0, TAU); ctx.fill();
  ctx.restore();
  // arms
  ctx.strokeStyle = suit;
  ctx.lineWidth = 4.4;
  ctx.beginPath();
  if (air) {
    ctx.moveTo(-7, -39); ctx.lineTo(-14, -30); ctx.lineTo(-17, -22);
    ctx.moveTo(7, -39); ctx.lineTo(14, -30); ctx.lineTo(12, -21);
  } else {
    ctx.moveTo(-7, -39); ctx.lineTo(-12 - swing * 4, -28); ctx.lineTo(-13 - swing2 * 5, -18);
    ctx.moveTo(7, -39); ctx.lineTo(12 + swing2 * 4, -28); ctx.lineTo(12 + swing * 5, -18);
  }
  ctx.stroke();
  ctx.strokeStyle = accent;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-15 - swing2 * 5, -18); ctx.lineTo(-11 - swing2 * 5, -18);
  ctx.moveTo(10 + swing * 5, -18); ctx.lineTo(14 + swing * 5, -18);
  ctx.stroke();
  // head
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.arc(1, -51, 8.4, 0, TAU);
  ctx.fill();
  ctx.fillStyle = suit;
  ctx.beginPath();
  ctx.arc(3, -51, 8.4, -.7, 1.7);
  ctx.fill();
  // visor
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glowCircle(ctx, 4, -52, 12, accent, .5);
  ctx.fillStyle = '#b7fcff';
  ctx.beginPath();
  ctx.ellipse(4, -52, 5.1, 2.7, -.1, 0, TAU);
  ctx.fill();
  ctx.restore();
  // shoulder light
  ctx.fillStyle = accent;
  ctx.fillRect(-8, -41, 2, 4);
  ctx.restore();
}

export function drawTimeRings(ctx, x, y, time, color, amount = 1) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const rr = 28 + Math.sin(time * 3) * 3;
  for (let i = 0; i < 3; i++) {
    ctx.strokeStyle = rgba(color, .22 - i * .055);
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 8]);
    ctx.beginPath();
    ctx.arc(x, y - 28, rr + i * 18, time * (1.1 + i * .2), time * (1.1 + i * .2) + TAU * .78);
    ctx.stroke();
  }
  ctx.setLineDash([]);
  // clock marks
  for (let i = 0; i < 12; i++) {
    const a = i / 12 * TAU + time * .12;
    ctx.globalAlpha = .15 + .14 * amount;
    ctx.fillStyle = color;
    const r1 = rr + 48, r2 = rr + 51;
    ctx.fillRect(x + Math.cos(a) * r1, y - 28 + Math.sin(a) * r1, 1.4, 1.4);
  }
  ctx.restore();
}

/* ============================================================
   TIME REWIND — frame compositor
   ============================================================ */

import {
  drawPlatform, drawLaser, drawSaw, drawCore, drawEnergy, drawCheckpoint,
  drawPortal, drawProjectile, drawSentinel, drawDrone, drawPlayer,
  drawTimeRings, glowCircle, rgba, roundRect
} from './draw.js';

const TAU = Math.PI * 2;

export class Renderer {
  constructor(game) {
    this.game = game;
    this.ctx = game.ctx;
  }

  render() {
    const g = this.game;
    const ctx = this.ctx;
    const dpr = g.dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = '#03040b';
    ctx.fillRect(0, 0, g.cssW, g.cssH);

    if (g.mode === 'menu' || g.mode === 'levels' || g.mode === 'how' || g.mode === 'settings') {
      this.drawMenuScene(ctx);
      return;
    }
    this.drawGameScene(ctx);
  }

  drawMenuScene(ctx) {
    const g = this.game;
    const w = g.cssW, h = g.cssH;
    const scale = Math.max(w / 1280, h / 720) * 1.03;
    const camX = (1280 - 1280) * .5;
    ctx.save();
    ctx.translate(w * .5, h * .5);
    ctx.scale(scale, scale);
    ctx.translate(-690, -360);
    g.background.draw(ctx, 0, 1380, g.ambientTime, g.reducedMotion);
    g.background.drawMenuMonument(ctx, g.ambientTime);
    // floating city debris
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 18; i++) {
      const t = g.ambientTime * (3 + i % 5) + i * 23;
      const x = 720 + ((i * 137) % 620);
      const y = 150 + ((i * 97) % 470) + Math.sin(t * .05) * 14;
      const a = .08 + (i % 4) * .025;
      ctx.globalAlpha = a;
      ctx.fillStyle = i % 3 ? '#7fe8ff' : '#c69bff';
      ctx.fillRect(x, y, 2, 7 + (i % 4) * 3);
    }
    ctx.restore();
    // slow sweeping scan light
    const sweep = (g.ambientTime * 30) % 1600;
    const sg = ctx.createLinearGradient(sweep, 0, sweep + 180, 0);
    sg.addColorStop(0, 'rgba(90,230,255,0)');
    sg.addColorStop(.5, 'rgba(90,230,255,.035)');
    sg.addColorStop(1, 'rgba(90,230,255,0)');
    ctx.fillStyle = sg;
    ctx.fillRect(0, 0, 1400, 720);
    ctx.restore();
  }

  drawGameScene(ctx) {
    const g = this.game;
    const viewW = g.viewW, viewH = g.viewH, scale = g.scale;
    const shake = this.computeShake();
    ctx.save();
    ctx.beginPath();
    ctx.rect(g.offsetX, g.offsetY, viewW * scale, viewH * scale);
    ctx.clip();
    ctx.translate(g.offsetX, g.offsetY);
    ctx.scale(scale, scale);
    ctx.translate(-g.camera.x + shake.x, -shake.y);
    this.drawWorld(ctx);
    ctx.restore();
    this.drawScreenFx(ctx);
  }

  computeShake() {
    const g = this.game;
    if (g.reducedMotion) return { x: 0, y: 0 };
    if (g.camera.shake <= 0.05) return { x: 0, y: 0 };
    const s = g.camera.shake;
    return {
      x: Math.sin(g.time * 87) * s + Math.cos(g.time * 51) * s * .45,
      y: Math.cos(g.time * 73) * s * .64 + Math.sin(g.time * 41) * s * .35
    };
  }

  drawWorld(ctx) {
    const g = this.game;
    const palette = g.level ? g.level.palette : g.background.palette;
    const t = g.worldTime;
    const echoActive = g.echoTimer > 0;

    g.background.draw(ctx, g.camera.x, g.viewW, g.ambientTime, g.reducedMotion);

    // ambient / decorative depth geometry
    this.drawDepthGeometry(ctx, palette, t);

    // platforms + hazards
    for (const p of g.platforms) drawPlatform(ctx, p, t, palette, echoActive, g.reducedMotion);
    for (const h of g.hazards) {
      if (h.type === 'laser') drawLaser(ctx, h, t, palette);
      else if (h.type === 'saw') drawSaw(ctx, h, t, palette);
    }

    for (const c of g.checkpoints) drawCheckpoint(ctx, c, t, palette, g.activeCheckpoints.has(c.id));

    if (g.portal) drawPortal(ctx, g.portal.x, g.portal.y, t, palette);

    for (const c of g.cores) drawCore(ctx, c, t, palette);
    for (const e of g.energyOrbs) drawEnergy(ctx, e, t);

    // enemy + projectiles
    for (const e of g.enemies) {
      if (e.type === 'sentinel') drawSentinel(ctx, e, t, palette);
      else if (e.type === 'drone') drawDrone(ctx, e, t, palette);
    }
    for (const p of g.projectiles) drawProjectile(ctx, p, t);

    // player afterimages
    this.drawPlayerGhosts(ctx, palette, scaleOfTrail(g));

    if (!g.dead && g.player) {
      if (g.invuln > 0) g.player.invuln = g.invuln;
      drawPlayer(ctx, g.player, t, palette, {});
      if (g.echoTimer > 0) {
        drawTimeRings(ctx, g.player.x, g.player.y, t, '#ffd36e', .7);
      }
    }

    // rewind rings and field
    if (g.rewinding) {
      drawTimeRings(ctx, g.player.x, g.player.y, t, '#57f2ff', 1);
      this.drawRewindField(ctx);
    }

    g.particles.draw(ctx);

    // low foreground mist over ground
    const fog = ctx.createLinearGradient(0, 620, 0, 745);
    fog.addColorStop(0, 'rgba(5,10,23,0)');
    fog.addColorStop(1, 'rgba(5,10,23,.66)');
    ctx.fillStyle = fog;
    ctx.fillRect(g.camera.x - 20, 615, g.viewW + 40, 140);
  }

  drawDepthGeometry(ctx, palette, time) {
    const g = this.game;
    // distant floating rings in the playfield air
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 3; i++) {
      const x = 230 + i * 390;
      const y = 170 + (i % 2) * 190;
      ctx.globalAlpha = .045 + (i % 2) * .015;
      ctx.strokeStyle = palette.accent;
      ctx.lineWidth = 18;
      ctx.beginPath();
      ctx.arc(x, y, 42 + i * 9, time * .05 + i, time * .05 + i + 2.3);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawPlayerGhosts(ctx, palette, intensity) {
    const g = this.game;
    if (!g.player || !g.history.length) return;
    const count = g.rewinding ? 6 : intensity > 70 ? 3 : 0;
    if (!count) return;
    const base = g.rewinding ? g.rewindCursor : g.history.length - 1;
    for (let i = 1; i <= count; i++) {
      const idx = Math.floor(g.rewinding ? base + i * 4 : base - i * 3);
      if (idx < 0 || idx >= g.history.length) continue;
      const snap = g.history[idx];
      if (!snap || !snap.player) continue;
      ctx.save();
      ctx.globalAlpha = (g.rewinding ? .2 : .055) * (1 - i / (count + 1));
      const ghost = { ...snap.player, invuln: 0, squash: 1 };
      drawPlayer(ctx, ghost, snap.time, palette, { ghost: true });
      ctx.restore();
    }
  }

  drawRewindField(ctx) {
    const g = this.game;
    const t = g.ambientTime;
    const x = g.player.x, y = g.player.y - 26;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const glow = ctx.createRadialGradient(x, y, 10, x, y, 230);
    glow.addColorStop(0, 'rgba(87,242,255,.14)');
    glow.addColorStop(.4, 'rgba(87,242,255,.035)');
    glow.addColorStop(1, 'rgba(87,242,255,0)');
    ctx.fillStyle = glow;
    ctx.beginPath(); ctx.arc(x, y, 230, 0, TAU); ctx.fill();
    // reverse rising ticks
    for (let i = 0; i < 16; i++) {
      const a = t * (1.2 + (i % 3) * .2) + i * 2.399;
      const r = 65 + ((t * 34 + i * 17) % 130);
      const px = x + Math.cos(a) * r;
      const py = y + Math.sin(a) * r * .72;
      ctx.globalAlpha = .16 * (1 - (r - 65) / 130);
      ctx.fillStyle = i % 2 ? '#57f2ff' : '#ffffff';
      ctx.fillRect(px, py, 1.5, 4);
    }
    // horizon scan
    ctx.globalAlpha = .11;
    ctx.fillStyle = '#57f2ff';
    for (let i = 0; i < 5; i++) {
      const yy = (t * 80 + i * 151) % 720;
      ctx.fillRect(g.camera.x, yy, g.viewW, 1);
    }
    ctx.restore();
  }

  drawScreenFx(ctx) {
    const g = this.game;
    const w = g.cssW, h = g.cssH;
    const dpr = g.dpr;
    ctx.save();
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    // death red wash
    if (g.dead) {
      const pulse = .08 + Math.sin(g.time * 5) * .025;
      const v = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * .2, w / 2, h / 2, Math.max(w, h) * .72);
      v.addColorStop(0, 'rgba(0,0,0,0)');
      v.addColorStop(.7, `rgba(89,8,33,${pulse})`);
      v.addColorStop(1, 'rgba(20,2,9,.7)');
      ctx.fillStyle = v;
      ctx.fillRect(0, 0, w, h);
    }

    if (g.rewinding && !g.reducedMotion) {
      const t = g.time;
      // cyan field
      const v = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * .08, w / 2, h / 2, Math.max(w, h) * .66);
      v.addColorStop(0, 'rgba(87,242,255,0)');
      v.addColorStop(.72, 'rgba(64,181,255,.035)');
      v.addColorStop(1, 'rgba(20,78,135,.16)');
      ctx.fillStyle = v;
      ctx.fillRect(0, 0, w, h);
      // chromatic side bands
      ctx.globalCompositeOperation = 'lighter';
      for (let i = 0; i < 6; i++) {
        const y = ((t * 260 + i * 137) % h);
        const x = (Math.sin(t * 3 + i) * .5 + .5) * w;
        ctx.globalAlpha = .045;
        ctx.fillStyle = i % 2 ? '#ff5fcd' : '#57f2ff';
        ctx.fillRect(x - w * .2, y, w * .4, 1.2);
      }
      ctx.globalAlpha = .12;
      ctx.strokeStyle = '#57f2ff';
      ctx.lineWidth = 1;
      ctx.strokeRect(w * .5 - 62, h * .5 - 62, 124, 124);
      ctx.globalAlpha = 1;
      // clock mark
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = 'rgba(87,242,255,.25)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(w / 2, h / 2, 53, -Math.PI / 2, -Math.PI / 2 + (1 - g.rewindCursor / Math.max(1, g.history.length - 1)) * TAU);
      ctx.stroke();
    }

    if (g.flash && g.flash.alpha > 0.002) {
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = g.flash.alpha;
      ctx.fillStyle = g.flash.color;
      ctx.fillRect(0, 0, w, h);
    }

    // top/bottom cinematic bars on narrow heights
    ctx.globalCompositeOperation = 'source-over';
    if (h < 560 && g.mode === 'playing') {
      ctx.fillStyle = 'rgba(2,4,11,.42)';
      ctx.fillRect(0, 0, w, 5);
      ctx.fillRect(0, h - 5, w, 5);
    }
    ctx.restore();
  }
}

function scaleOfTrail(g) {
  return Math.abs(g.player?.vx || 0);
}

/* ============================================================
   TIME REWIND — game controller
   ============================================================ */

import { LEVELS, TOTAL_CORES } from './levels.js';
import { SaveStore } from './save.js';
import { AudioEngine } from './audio.js';
import { ParticleField } from './particles.js';
import { UIManager, formatTime } from './ui.js';
import { Background } from './background.js';
import { Renderer } from './renderer.js';
import {
  STEP, HISTORY_MAX, ECHO_WINDOW, clamp,
  fixedUpdate, startRewind, endRewind, killPlayer, respawnPlayer,
  captureSnapshot, setupBodies
} from './systems.js';

export class Game {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.saveStore = new SaveStore();
    this.save = this.saveStore.data;
    this.audio = new AudioEngine();
    this.particles = new ParticleField();

    this.mode = 'menu';
    this.levelIndex = -1;
    this.level = null;
    this.background = new Background(LEVELS[0]);

    this.platforms = [];
    this.hazards = [];
    this.enemies = [];
    this.projectiles = [];
    this.cores = [];
    this.energyOrbs = [];
    this.checkpoints = [];
    this.portal = null;
    this.player = null;

    this.rewinding = false;
    this.rewindCursor = 0;
    this.rewindAmount = 0;
    this.recoil = 0;
    this.dead = false;
    this.deadTimer = 0;
    this.deathWait = 3.2;
    this.deathsThisRun = 0;
    this.checkpointIndex = -1;
    this.activeCheckpoints = new Set();
    this.coreCollected = new Set();
    this.echoTimer = 0;
    this.echoAnnounced = false;
    this.invuln = 0;
    this.timeEnergy = 100;
    this.levelTimer = 0;
    this.worldTime = 0;
    this.ambientTime = 0;
    this.time = 0;
    this.history = [];
    this.sampleTimer = 0;
    this.hintDelay = 0;
    this.hintCooldown = 0;
    this.hintsShown = new Set();
    this.camera = { x: 0, y: 0, shake: 0 };
    this.flash = { color: '#57f2ff', alpha: 0 };
    this.reducedMotion = this.save.settings.reducedMotion;
    this.god = false;

    this.input = {
      left: false, right: false, jumpHeld: false, jumpBuffer: 0, rewind: false
    };

    this.cssW = window.innerWidth;
    this.cssH = window.innerHeight;
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.viewW = 1280;
    this.viewH = 720;
    this.scale = 1;
    this.offsetX = 0;
    this.offsetY = 0;

    this.ui = new UIManager(this);
    this.renderer = new Renderer(this);
    this.applySettings();
    this.bindInput();
    this.resize();
    this.showMenu();

    this.lastFrame = performance.now();
    this.accumulator = 0;
    this.hudClock = 0;
    this.loop = this.loop.bind(this);
    requestAnimationFrame(this.loop);
  }

  /* ------------------------------------------------------------ */
  /* lifecycle / render loop                                      */
  /* ------------------------------------------------------------ */

  loop(now) {
    const raw = (now - this.lastFrame) / 1000;
    this.lastFrame = now;
    const dt = Math.min(0.05, Math.max(0, raw));
    this.time += dt;
    this.ambientTime += dt;
    this.audio.update();

    if (this.mode === 'playing') {
      this.accumulator += dt;
      let steps = 0;
      while (this.accumulator >= STEP && steps < 6) {
        fixedUpdate(this, STEP);
        this.accumulator -= STEP;
        steps++;
      }
    } else {
      this.accumulator = 0;
    }

    const particleSpeed = this.mode === 'paused' || this.mode === 'complete' ? 0.08 : this.rewinding ? 0.45 : 1;
    this.particles.update(dt * particleSpeed);
    this.flash.alpha *= Math.exp(-dt * 6.5);
    if (this.flash.alpha < 0.002) this.flash.alpha = 0;
    this.camera.shake *= Math.exp(-dt * 7.5);
    if (this.camera.shake < 0.04) this.camera.shake = 0;

    if (this.mode === 'playing') this.updateCamera(dt);
    if (this.mode === 'menu') this.emitMenuMotes(dt);

    this.hudClock += dt;
    if (this.hudClock > 0.07 && (this.mode === 'playing' || this.dead)) {
      this.hudClock = 0;
      this.refreshHud();
    }
    this.renderer.render();
    requestAnimationFrame(this.loop);
  }

  updateCamera(dt) {
    const maxX = Math.max(0, 1280 - this.viewW);
    let target = 0;
    if (this.player) target = clamp(this.player.x - this.viewW * 0.43, 0, maxX);
    if (this.dead && this.player) target = clamp(this.player.x - this.viewW * 0.43, 0, maxX);
    const speed = this.dead ? 2.2 : 6.5;
    this.camera.x += (target - this.camera.x) * Math.min(1, dt * speed);
    this.camera.x = clamp(this.camera.x, 0, maxX);
  }

  resize() {
    const rect = this.canvas.getBoundingClientRect();
    const w = Math.max(280, rect.width || window.innerWidth);
    const h = Math.max(220, rect.height || window.innerHeight);
    this.cssW = w;
    this.cssH = h;
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.canvas.width = Math.round(w * this.dpr);
    this.canvas.height = Math.round(h * this.dpr);
    this.viewH = 720;
    const aspect = w / h;
    this.viewW = clamp(720 * aspect, 430, 1280);
    this.scale = Math.min(w / this.viewW, h / this.viewH);
    this.offsetX = (w - this.viewW * this.scale) / 2;
    this.offsetY = (h - this.viewH * this.scale) / 2;
    if (this.player) {
      this.camera.x = clamp(this.camera.x, 0, Math.max(0, 1280 - this.viewW));
    }
  }

  emitMenuMotes(dt) {
    if (Math.random() < dt * 1.8) {
      this.particles.add({
        x: 700 + Math.random() * 540,
        y: 210 + Math.random() * 380,
        vx: -4 - Math.random() * 7,
        vy: -2 - Math.random() * 7,
        life: 4 + Math.random() * 5,
        size: .5 + Math.random() * 1.3,
        color: Math.random() > .5 ? '#7deeff' : '#bca4ff',
        drag: .03,
        alpha: .6
      });
    }
  }

  /* ------------------------------------------------------------ */
  /* navigation                                                   */
  /* ------------------------------------------------------------ */

  showMenu() {
    this.mode = 'menu';
    this.ui.hideAllScreens();
    this.ui.showMenu(this.save, this.save.unlocked > 1 ? this.save.lastLevelData : null);
    this.ui.hideHud();
    this.ui.hideHint();
    this.ui.hideDeath();
    this.ui.intro.classList.add('is-hidden');
    this.rewinding = false;
    this.dead = false;
    this.audio.setPaused(false);
    this.audio.rewindStop(true);
    this.audio.setEnabled(this.save.settings.audio);
    this.background = new Background(LEVELS[0]);
    this.flash.alpha = 0;
  }

  openMenu() {
    this.showMenu();
  }

  openLevels(fromPause = false) {
    this.mode = 'levels';
    this.ui.showLevels(this.save);
    this.ui.hideHud();
    this.ui.hideDeath();
    this.ui.hideHint();
    this.ui.intro.classList.add('is-hidden');
    this.audio.setPaused(true);
    this.rewinding = false;
    this.dead = false;
    if (fromPause) this.audio.rewindStop(true);
  }

  openHow() {
    this.mode = 'how';
    this.ui.show('how');
    this.ui.hideHud();
    this.ui.hideHint();
    this.ui.intro.classList.add('is-hidden');
  }

  openSettings() {
    this.mode = 'settings';
    this.ui.show('settings');
    this.ui.refreshSettings(this.save);
    this.ui.hideHud();
    this.ui.hideHint();
    this.ui.intro.classList.add('is-hidden');
  }

  playFromMenu() {
    const hasProgress = this.save.unlocked > 1 || Object.keys(this.save.completed).length > 0;
    const index = hasProgress ? clamp(this.save.lastLevel, 0, LEVELS.length - 1) : 0;
    this.startSector(index);
  }

  continueRun() {
    this.startSector(clamp(this.save.lastLevel, 0, LEVELS.length - 1));
  }

  startSector(index) {
    if (index < 0 || index >= LEVELS.length) return;
    if (index >= this.save.unlocked && !this.god) {
      this.ui.showToast('LOCKED', 'Restore the previous sector first.');
      return;
    }
    this.levelIndex = index;
    this.saveStore.setLastLevel(index);
    this.save = this.saveStore.data;
    this.deathsThisRun = 0;
    this.levelTimer = 0;
    this.checkpointIndex = -1;
    this.activeCheckpoints.clear();
    this.coreCollected.clear();
    this.hintsShown.clear();
    this.respawn = { ...LEVELS[index].spawn };
    this.mode = 'playing';
    this.ui.hideAllScreens();
    this.ui.hideDeath();
    this.ui.intro.classList.add('is-hidden');
    this.setupLevel(index, { fresh: true });
    this.ui.showHud(this.level);
    this.ui.showIntro(this.level);
    this.audio.setPaused(false);
    this.audio.setEnabled(this.save.settings.audio);
    this.audio.setLevel(index);
    this.audio.unlock();
    this.audio.portal();
    this.hintDelay = 2.25;
    this.camera.x = clamp(this.player.x - this.viewW * 0.43, 0, Math.max(0, 1280 - this.viewW));
    this.refreshHud(true);
  }

  setupLevel(index, { fresh = false } = {}) {
    const data = LEVELS[index];
    this.level = data;
    this.background = new Background(data);
    this.projectiles = [];
    this.history = [];
    this.sampleTimer = 0;
    this.rewindCursor = 0;
    this.rewindAmount = 0;
    this.worldTime = 0;
    this.echoTimer = 0;
    this.echoAnnounced = false;
    this.rewinding = false;
    this.dead = false;
    this.deadTimer = 0;
    this.invuln = 1.15;
    this.timeEnergy = 100;
    this.flash = { color: data.palette.accent, alpha: .18 };
    this.camera.shake = 0;
    this.input.jumpBuffer = 0;
    this.input.rewind = false;

    this.platforms = data.platforms.map((p, i) => ({
      ...p,
      id: i,
      kind: p.kind || 'solid',
      baseX: p.x,
      baseY: p.y,
      curX: p.x,
      curY: p.y,
      prevX: p.x,
      prevY: p.y,
      dx: 0,
      dy: 0,
      state: 0,
      timer: 0,
      fall: 0,
      phaseActive: true
    }));
    this.hazards = data.hazards.map((h) => ({ ...h }));
    this.cores = data.cores.map((c, i) => ({
      ...c,
      id: `${data.id}:${i}`,
      idx: i,
      collected: this.coreCollected.has(`${data.id}:${i}`)
    }));
    this.energyOrbs = data.energy.map((e, i) => ({ ...e, idx: i, collected: false }));
    this.checkpoints = data.checkpoints.map((c) => ({ ...c, active: this.activeCheckpoints.has(c.id) }));
    this.portal = { ...data.portal };
    this.enemies = setupBodies(data.enemies);
    this.levelTimer = fresh ? 0 : this.levelTimer;

    const spawn = fresh ? data.spawn : (this.respawn || data.spawn);
    this.player = {
      x: spawn.x, y: spawn.y, vx: 0, vy: 0,
      facing: 1, onGround: true, coyote: 0, jumpBuffer: 0,
      runPhase: 0, squash: 1, groundId: -1, jumpCut: false,
      alive: true, invuln: this.invuln, stepTimer: 0
    };
    this.updatePlatformState(0);
    this.snapCamera();
    this.recordSnapshot(true);
  }

  snapCamera() {
    this.camera.x = clamp(this.player.x - this.viewW * 0.43, 0, Math.max(0, 1280 - this.viewW));
  }

  restartSector() {
    if (this.levelIndex < 0) return;
    this.audio.click();
    this.startSector(this.levelIndex);
  }

  replaySector() {
    this.startSector(this.levelIndex);
  }

  nextSector() {
    if (this.levelIndex >= LEVELS.length - 1) {
      this.openLevels();
      return;
    }
    this.startSector(this.levelIndex + 1);
  }

  pause() {
    if (this.mode !== 'playing') return;
    this.mode = 'paused';
    this.audio.setPaused(true);
    this.ui.showPause({
      number: this.level.number,
      time: this.levelTimer,
      cores: this.coreCollected.size
    });
    this.ui.hideHint();
    if (this.dead) this.ui.hideDeath();
  }

  resume() {
    if (this.mode !== 'paused') return;
    this.mode = 'playing';
    this.ui.hideAllScreens();
    this.audio.setPaused(false);
    this.lastFrame = performance.now();
    if (this.dead) this.ui.showDeath(this.timeEnergy, this.deathWait);
  }

  toggleMute() {
    this.save.settings.audio = !this.save.settings.audio;
    this.saveStore.data.settings.audio = this.save.settings.audio;
    this.saveStore.save();
    this.audio.setEnabled(this.save.settings.audio);
    this.ui.setMute(!this.save.settings.audio, true);
    this.ui.showToast('AUDIO', this.save.settings.audio ? 'Soundscape online.' : 'Soundscape muted.', 1800);
  }

  toggleReducedMotion() {
    this.save.settings.reducedMotion = !this.save.settings.reducedMotion;
    this.saveStore.data.settings.reducedMotion = this.save.settings.reducedMotion;
    this.saveStore.save();
    this.applySettings();
    this.ui.refreshSettings(this.save);
  }

  toggleScreenFx() {
    this.save.settings.screenFx = !this.save.settings.screenFx;
    this.saveStore.data.settings.screenFx = this.save.settings.screenFx;
    this.saveStore.save();
    this.applySettings();
    this.ui.refreshSettings(this.save);
  }

  applySettings() {
    this.reducedMotion = this.save.settings.reducedMotion;
    document.body.classList.toggle('no-fx', !this.save.settings.screenFx);
    document.body.classList.toggle('reduced-motion', this.reducedMotion);
    this.audio.setEnabled(this.save.settings.audio);
    this.ui.setMute(!this.save.settings.audio, true);
  }

  resetProgress() {
    const ok = window.confirm('Purge the entire timeline? All sectors, cores and best times will be erased.');
    if (!ok) return;
    this.saveStore.reset();
    this.save = this.saveStore.data;
    this.applySettings();
    this.ui.refreshSettings(this.save);
    this.ui.showToast('ARCHIVE PURGED', 'A new timeline begins.');
  }

  completeLevel() {
    if (this.mode !== 'playing' || !this.level) return;
    this.mode = 'complete';
    this.rewinding = false;
    this.audio.rewindStop(true);
    this.audio.setPaused(true);
    this.audio.portal();
    this.ui.setRewinding(false);
    this.ui.hideHint();
    this.ui.hideDeath();
    const cores = this.coreCollected.size;
    const result = this.saveStore.completeLevel(this.levelIndex, {
      time: this.levelTimer,
      deaths: this.deathsThisRun,
      cores
    });
    this.save = this.saveStore.data;
    const final = this.levelIndex >= LEVELS.length - 1;
    this.ui.showComplete({
      final,
      level: this.level,
      time: this.levelTimer,
      deaths: this.deathsThisRun,
      cores,
      totalCores: this.level.cores.length,
      stars: result ? result.stars : 1,
      bestTime: result ? result.bestTime : this.levelTimer,
      newRecord: result ? result.newRecord : true
    });
    if (!final) this.audio.unlockSfx();
    this.saveStore.save();
  }

  refreshHud(force = false) {
    if (!this.level || !this.player) return;
    this.ui.updateHud({
      energy: this.timeEnergy,
      time: this.levelTimer,
      cores: this.coreCollected.size,
      totalCores: this.level.cores.length,
      checkpoint: this.checkpointIndex,
      rewinding: this.rewinding,
      rewindSeconds: this.rewindAmount,
      echo: this.echoTimer
    });
    if (this.dead) {
      this.ui.updateDeath(Math.max(0, this.deathWait - this.deadTimer), this.deathWait);
    }
  }

  /* ------------------------------------------------------------ */
  /* input                                                         */
  /* ------------------------------------------------------------ */

  bindInput() {
    window.addEventListener('keydown', (e) => {
      const code = e.code;
      const playing = this.mode === 'playing';
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(code)) {
        if (playing) e.preventDefault();
      }
      this.audio.unlock();
      if (e.repeat) return;
      if (code === 'KeyA' || code === 'ArrowLeft') this.setMove('left', true);
      else if (code === 'KeyD' || code === 'ArrowRight') this.setMove('right', true);
      else if (code === 'Space' || code === 'KeyW' || code === 'ArrowUp') {
        if (playing) this.pressJump();
      } else if (code === 'KeyR' || code === 'ShiftLeft' || code === 'ShiftRight') {
        if (playing) this.setRewind(true);
      } else if (code === 'Escape' || code === 'KeyP') {
        this.handleEscape();
      } else if (code === 'KeyM') {
        this.toggleMute();
      } else if (code === 'Enter') {
        if (this.mode === 'menu') this.playFromMenu();
        else if (this.mode === 'paused') this.resume();
      }
    }, { passive: false });

    window.addEventListener('keyup', (e) => {
      const code = e.code;
      if (code === 'KeyA' || code === 'ArrowLeft') this.setMove('left', false);
      else if (code === 'KeyD' || code === 'ArrowRight') this.setMove('right', false);
      else if (code === 'Space' || code === 'KeyW' || code === 'ArrowUp') this.releaseJump();
      else if (code === 'KeyR' || code === 'ShiftLeft' || code === 'ShiftRight') this.setRewind(false);
    });

    document.addEventListener('visibilitychange', () => {
      if (document.hidden && this.mode === 'playing') this.pause();
    });
    window.addEventListener('blur', () => {
      if (this.mode === 'playing') this.pause();
    });
  }

  handleEscape() {
    if (this.mode === 'playing') this.pause();
    else if (this.mode === 'paused') this.resume();
    else if (this.mode === 'levels' || this.mode === 'how' || this.mode === 'settings') this.openMenu();
    else if (this.mode === 'complete') this.openLevels();
  }

  setMove(dir, pressed) {
    this.input[dir] = pressed;
  }

  pressJump() {
    this.input.jumpHeld = true;
    this.input.jumpBuffer = 0.13;
  }

  releaseJump() {
    this.input.jumpHeld = false;
  }

  setRewind(pressed) {
    this.input.rewind = pressed;
    if (pressed) {
      if (this.mode === 'playing' && !this.rewinding) this.beginRewind();
    } else if (this.rewinding) {
      this.finishRewind();
    }
  }

  /* ------------------------------------------------------------ */
  /* rewind wrappers (systems implement the heavy lifting)        */
  /* ------------------------------------------------------------ */

  beginRewind() {
    startRewind(this);
  }

  finishRewind() {
    endRewind(this);
  }

  die(cause = 'fracture') {
    killPlayer(this, cause);
  }

  respawn() {
    respawnPlayer(this);
  }

  recordSnapshot(force = false) {
    if (!this.player) return;
    this.history.push(captureSnapshot(this));
    if (this.history.length > HISTORY_MAX + 1) this.history.shift();
  }

  updatePlatformState(dt) {
    for (const p of this.platforms) {
      p.prevX = p.curX;
      p.prevY = p.curY;
      if (p.move) {
        const period = p.move.period || 4;
        const ph = p.move.phase || 0;
        const e = 0.5 - 0.5 * Math.cos(((this.worldTime / period) + ph) * Math.PI * 2);
        p.curX = p.baseX + (p.move.dx || 0) * e;
        p.curY = p.baseY + (p.move.dy || 0) * e;
      } else {
        p.curX = p.baseX;
        p.curY = p.baseY;
      }
      p.dx = p.curX - p.prevX;
      p.dy = p.curY - p.prevY;
      if (p.kind === 'phase') {
        const period = p.period || 3;
        const c = ((this.worldTime + (p.phase || 0)) % period) / period;
        p.phaseActive = c < (p.duty || 0.6);
      }
    }
  }

  /* ------------------------------------------------------------ */
  /* debug hooks used by automated verification                   */
  /* ------------------------------------------------------------ */

  installDebugApi() {
    const game = this;
    const api = {
      game,
      levels: LEVELS,
      start: (i) => game.startSector(i),
      state: () => ({
        mode: game.mode,
        level: game.levelIndex,
        x: game.player?.x, y: game.player?.y,
        vx: game.player?.vx, vy: game.player?.vy,
        energy: game.timeEnergy,
        rewinding: game.rewinding,
        dead: game.dead,
        history: game.history.length,
        cores: game.coreCollected.size,
        checkpoint: game.checkpointIndex,
        echo: game.echoTimer,
        unlocked: game.save.unlocked,
        completed: Object.keys(game.save.completed).length,
        platforms: game.platforms.map(p => ({ x: p.curX, y: p.curY, w: p.w, h: p.h, kind: p.kind, state: p.state, phaseActive: p.phaseActive }))
      }),
      teleport: (x, y) => {
        if (!game.player) return;
        game.player.x = x; game.player.y = y; game.player.vx = 0; game.player.vy = 0;
        game.snapCamera();
      },
      win: () => game.completeLevel(),
      kill: () => game.die('debug'),
      setEnergy: (v) => { game.timeEnergy = clamp(v, 0, 100); },
      setGod: (v) => { game.god = !!v; },
      unlockAll: () => {
        game.save.unlocked = LEVELS.length;
        game.saveStore.save();
      },
      clearHistory: () => { game.history.length = 0; },
      setWorldTime: (t) => { game.worldTime = t; },
      step: (n = 1) => { for (let i = 0; i < n; i++) fixedUpdate(game, STEP); },
      getLevel: (i) => LEVELS[i],
      resetSave: () => { game.saveStore.reset(); game.save = game.saveStore.data; }
    };
    window.TIME_REWIND = api;
    window.__TIME_REWIND__ = api;
  }
}

export { TOTAL_CORES, formatTime };

/* ============================================================
   TIME REWIND — simulation systems
   ============================================================ */

export const STEP = 1 / 60;
export const SAMPLE_RATE = 30;
export const HISTORY_MAX = 150;
export const ECHO_WINDOW = 4.0;

const GRAVITY = 2360;
const MOVE_SPEED = 342;
const GROUND_ACCEL = 2900;
const AIR_ACCEL = 1800;
const GROUND_FRICTION = 3200;
const AIR_FRICTION = 260;
const JUMP_SPEED = 772;
const MAX_FALL = 1060;
const COYOTE = 0.095;
const PLAYER_W = 30;
const PLAYER_H = 52;
const REWIND_PLAYBACK = 1.62;
const REWIND_DRAIN = 24.5;
const ENERGY_REGEN = 1.8;

const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
const lerp = (a, b, t) => a + (b - a) * t;
const sign = (n) => n < 0 ? -1 : n > 0 ? 1 : 0;
const TAU = Math.PI * 2;

export function fixedUpdate(game, dt) {
  if (game.mode !== 'playing') return;

  if (game.dead) {
    game.deadTimer += dt;
    if (game.deadTimer >= game.deathWait) respawnPlayer(game);
    return;
  }

  if (game.rewinding) {
    updateRewind(game, dt);
    return;
  }

  game.levelTimer += dt;
  game.worldTime += dt;
  game.invuln = Math.max(0, game.invuln - dt);
  if (game.invuln > 0 && game.player) game.player.invuln = game.invuln;
  if (game.echoTimer > 0) {
    game.echoTimer = Math.max(0, game.echoTimer - dt);
    if (game.echoTimer === 0 && game.platforms.some(p => p.kind === 'echo')) {
      game.ui.showToast('ECHO FADED', 'The afterglow has collapsed.', 1400);
    }
  }

  game.updatePlatformState(dt);
  updateCrumbles(game, dt);
  updateEnemies(game, dt);
  updateProjectiles(game, dt);
  updatePlayer(game, dt);
  updatePickups(game);
  updateCheckpoints(game);
  updateHints(game, dt);
  updatePortal(game, dt);

  // recharge the chrono reserve slowly
  if (!game.dead) game.timeEnergy = clamp(game.timeEnergy + ENERGY_REGEN * dt, 0, 100);

  if (!game.god && game.player && game.player.y > 790) killPlayer(game, 'void');

  // record the last five seconds at 30 Hz
  game.sampleTimer += dt;
  const interval = 1 / SAMPLE_RATE;
  while (game.sampleTimer >= interval) {
    game.sampleTimer -= interval;
    game.recordSnapshot();
  }

  if (!game.dead) checkDanger(game);
}

/* ============================================================
   player
   ============================================================ */

function solid(game, p) {
  if (p.kind === 'phase' && !p.phaseActive) return false;
  if (p.kind === 'echo' && game.echoTimer <= 0) return false;
  if (p.kind === 'crumble' && p.state >= 2) return false;
  return true;
}

function playerRect(p, inset = 0) {
  return {
    x: p.x - PLAYER_W / 2 + inset,
    y: p.y - PLAYER_H + inset,
    w: PLAYER_W - inset * 2,
    h: PLAYER_H - inset * 2
  };
}

function updatePlayer(game, dt) {
  const p = game.player;
  const input = game.input;
  if (!p) return;

  p.jumpBuffer = Math.max(0, p.jumpBuffer - dt);
  const wasGrounded = p.onGround;
  p.coyote = wasGrounded ? COYOTE : Math.max(0, p.coyote - dt);

  // carry momentum from a moving platform
  if (p.groundId >= 0) {
    const gp = game.platforms[p.groundId];
    if (gp && solid(game, gp) && wasGrounded) {
      p.x += gp.dx;
      p.y += gp.dy;
    }
  }

  const dir = (input.right ? 1 : 0) - (input.left ? 1 : 0);
  const accel = wasGrounded ? GROUND_ACCEL : AIR_ACCEL;
  if (dir !== 0) {
    const target = dir * MOVE_SPEED;
    if (p.vx < target) p.vx = Math.min(target, p.vx + accel * dt);
    else if (p.vx > target) p.vx = Math.max(target, p.vx - accel * dt);
    p.facing = dir;
  } else {
    const friction = (wasGrounded ? GROUND_FRICTION : AIR_FRICTION) * dt;
    if (Math.abs(p.vx) <= friction) p.vx = 0;
    else p.vx -= sign(p.vx) * friction;
  }

  // jump — with coyote time and input buffering
  if (input.jumpBuffer > 0 && (wasGrounded || p.coyote > 0)) {
    p.vy = -JUMP_SPEED;
    p.onGround = false;
    p.groundId = -1;
    p.coyote = 0;
    p.jumpCut = false;
    input.jumpBuffer = 0;
    p.squash = 0.86;
    game.audio.jump();
    game.particles.jump(p.x, p.y, game.level.palette.accent);
  }

  if (!input.jumpHeld && p.vy < -250 && !p.jumpCut) {
    p.vy = Math.max(p.vy, -255);
    p.jumpCut = true;
  }
  if (input.jumpHeld) p.jumpCut = false;

  const oldVy = p.vy;
  p.vy = Math.min(MAX_FALL, p.vy + GRAVITY * dt);
  p.onGround = false;
  p.groundId = -1;

  // horizontal phase
  const prevX = p.x;
  p.x += p.vx * dt;
  const body = playerRect(p, 1);

  for (const plat of game.platforms) {
    if (!solid(game, plat)) continue;
    const pr = { x: plat.curX, y: plat.curY, w: plat.w, h: plat.h };
    if (!rectsOverlap(body, pr)) continue;
    if (body.y + body.h <= pr.y + 1.5) continue;
    if (body.y >= pr.y + pr.h - 1.5) continue;
    if (p.vx > 0) {
      p.x = pr.x - PLAYER_W / 2 - 0.5;
    } else if (p.vx < 0) {
      p.x = pr.x + pr.w + PLAYER_W / 2 + 0.5;
    } else {
      const pushLeft = (body.x + body.w) - pr.x;
      const pushRight = (pr.x + pr.w) - body.x;
      p.x += pushLeft < pushRight ? -pushLeft - .5 : pushRight + .5;
    }
    p.vx = 0;
    body.x = p.x - PLAYER_W / 2 + 1;
    break;
  }

  // vertical phase
  const prevY = p.y;
  p.y += p.vy * dt;
  const nextBody = playerRect(p, 1);
  let landing = null;
  let ceiling = null;

  for (const plat of game.platforms) {
    if (!solid(game, plat)) continue;
    const pr = { x: plat.curX, y: plat.curY, w: plat.w, h: plat.h };
    if (nextBody.x + nextBody.w <= pr.x + 1 || nextBody.x >= pr.x + pr.w - 1) continue;

    if (p.vy >= 0) {
      const snap = Math.max(8, Math.abs(plat.dy) + 5);
      if (prevY <= pr.y + snap && p.y >= pr.y && nextBody.y < pr.y + pr.h - 1) {
        if (!landing || pr.y < landing.curY) landing = plat;
      }
    } else {
      if (prevY - PLAYER_H >= pr.y + pr.h - 3 && nextBody.y <= pr.y + pr.h && p.y > pr.y) {
        if (!ceiling || pr.y + pr.h > ceiling.curY + ceiling.h) ceiling = plat;
      }
    }
  }

  if (landing) {
    p.y = landing.curY;
    p.vy = 0;
    p.onGround = true;
    p.groundId = landing.id;
    p.squash = Math.min(p.squash, 0.9);
    if (oldVy > 410) {
      game.audio.land();
      game.particles.land(p.x, p.y, game.level.palette.accent);
      if (!game.reducedMotion) game.camera.shake = Math.min(4.5, oldVy / 260);
    }
    if (landing.kind === 'crumble' && landing.state === 0) triggerCrumble(game, landing);
  } else if (ceiling) {
    p.y = ceiling.curY + ceiling.h + PLAYER_H + 0.2;
    p.vy = Math.max(0, p.vy);
  }

  if (p.x < 18) { p.x = 18; p.vx = Math.max(0, p.vx); }
  if (p.x > 1262) { p.x = 1262; p.vx = Math.min(0, p.vx); }

  p.squash += (1 - p.squash) * Math.min(1, dt * 10);
  if (p.onGround && Math.abs(p.vx) > 25) {
    p.runPhase += (Math.abs(p.vx) / MOVE_SPEED) * dt * 15;
    p.stepTimer -= dt;
    if (p.stepTimer <= 0) {
      p.stepTimer = 0.1;
      game.particles.run(p.x, p.y, p.facing, game.level.palette.accent);
    }
  } else if (!p.onGround) {
    p.runPhase += dt * 3;
  }
}

function triggerCrumble(game, plat) {
  plat.state = 1;
  plat.timer = 0.72;
  game.audio.noise(0.12, 0.025, 1200);
  for (let i = 0; i < 8; i++) {
    game.particles.add({
      x: plat.curX + Math.random() * plat.w,
      y: plat.curY + 2,
      vx: (Math.random() - .5) * 50,
      vy: -20 - Math.random() * 30,
      life: .4 + Math.random() * .4,
      size: 1 + Math.random() * 1.6,
      color: '#ffb15f',
      gravity: 170,
      drag: 1
    });
  }
}

function updateCrumbles(game, dt) {
  for (const p of game.platforms) {
    if (p.kind !== 'crumble') continue;
    if (p.state === 1) {
      p.timer -= dt;
      if (p.timer <= 0) {
        p.state = 2;
        p.timer = 2.15;
        p.fall = 0;
        p.shake = 0;
        game.audio.noise(0.22, 0.035, 550);
        for (let i = 0; i < 10; i++) {
          game.particles.add({
            x: p.curX + Math.random() * p.w,
            y: p.curY + 4,
            vx: (Math.random() - .5) * 90,
            vy: -10 + Math.random() * 40,
            life: .5 + Math.random() * .6,
            size: 1 + Math.random() * 2,
            color: '#ffb15f',
            gravity: 280
          });
        }
      }
    } else if (p.state === 2) {
      p.timer -= dt;
      p.fall += (220 + (2.15 - p.timer) * 130) * dt;
      if (p.timer <= 0) {
        p.state = 0;
        p.timer = 0;
        p.fall = 0;
      }
    }
  }
}

/* ============================================================
   enemies
   ============================================================ */

export function setupBodies(enemies) {
  return enemies.map((e, i) => {
    if (e.type === 'sentinel') {
      return {
        ...e, id: i, dir: 1, state: 'patrol', alertT: 0,
        alert: false, step: Math.random() * 10, phase: i * 1.7
      };
    }
    return {
      ...e, id: i, baseX: e.x, baseY: e.y,
      fireTimer: (e.fireRate || 2.4) * (0.55 + (i % 3) * .14),
      alert: false, phase: i * 2.1, step: 0
    };
  });
}

function updateEnemies(game, dt) {
  const p = game.player;
  if (!p) return;
  for (const e of game.enemies) {
    if (e.type === 'sentinel') {
      const dx = p.x - e.x;
      const dy = p.y - e.y;
      const canSee = Math.abs(dx) < 315 && dy > -120 && dy < 95 && !game.dead;
      if (canSee) {
        if (e.state !== 'chase') {
          game.particles.enemyAlert(e.x, e.y - 28);
          game.audio.tone(180, .18, 'sawtooth', .035, 80);
        }
        e.state = 'chase';
        e.alert = true;
        e.alertT = 2.1;
        e.dir = sign(dx) || e.dir;
      } else {
        e.alertT -= dt;
        if (e.alertT <= 0) { e.state = 'patrol'; e.alert = false; }
      }
      const speed = e.state === 'chase' ? e.speed * 2.05 : e.speed;
      e.x += e.dir * speed * dt;
      if (e.x <= e.minX) { e.x = e.minX; e.dir = 1; }
      if (e.x >= e.maxX) { e.x = e.maxX; e.dir = -1; }
      e.step += dt * (speed * .13 + 2);
    } else if (e.type === 'drone') {
      const dx = p.x - e.x;
      const dy = (p.y - 26) - e.y;
      const dist = Math.hypot(dx, dy);
      const inRange = dist < (e.range || 360) && !game.dead;
      if (inRange) {
        if (!e.alert) game.particles.enemyAlert(e.x, e.y - 15);
        e.alert = true;
        const targetX = p.x + (Math.abs(dx) < 60 ? 120 : 0);
        const targetY = p.y - 165;
        const speed = 74;
        e.x += clamp(targetX - e.x, -speed * dt, speed * dt);
        e.y += clamp(targetY - e.y, -speed * dt, speed * dt);
        e.x = clamp(e.x, 40, 1240);
        e.y = clamp(e.y, 85, 480);
        e.fireTimer -= dt;
        if (e.fireTimer <= 0 && game.invuln <= 0) {
          e.fireTimer = (e.fireRate || 2.4) * (0.9 + Math.random() * 0.2);
          fireBolt(game, e, p);
        }
      } else {
        e.alert = false;
        e.x += clamp(e.baseX - e.x, -52 * dt, 52 * dt);
        e.y += clamp(e.baseY - e.y, -52 * dt, 52 * dt);
      }
    }
  }
}

function fireBolt(game, e, p) {
  const sx = e.x, sy = e.y + 6;
  const tx = p.x, ty = p.y - 28;
  const a = Math.atan2(ty - sy, tx - sx);
  const speed = 305;
  game.projectiles.push({
    x: sx, y: sy,
    vx: Math.cos(a) * speed, vy: Math.sin(a) * speed,
    life: 4.5, radius: 5.5, trail: 0
  });
  game.audio.tone(720, .12, 'square', .024, 1040);
  game.particles.add({ type: 'ring', x: sx, y: sy, size: 2, grow: 20, life: .25, color: '#ff5f7e', width: 1 });
  for (let i = 0; i < 5; i++) {
    game.particles.add({
      x: sx, y: sy, vx: Math.cos(a) * 70 + (Math.random() - .5) * 60,
      vy: Math.sin(a) * 70 + (Math.random() - .5) * 60,
      life: .2 + Math.random() * .2, size: 1.2, color: '#ff7d96', drag: 2
    });
  }
}

function updateProjectiles(game, dt) {
  for (let i = game.projectiles.length - 1; i >= 0; i--) {
    const b = game.projectiles[i];
    b.x += b.vx * dt;
    b.y += b.vy * dt;
    b.life -= dt;
    b.trail = (b.trail || 0) - dt;
    if (b.life <= 0 || b.x < -40 || b.x > 1320 || b.y < -40 || b.y > 780) {
      game.projectiles.splice(i, 1);
    }
  }
}

/* ============================================================
   world objects
   ============================================================ */

function updatePickups(game) {
  const p = game.player;
  if (!p) return;
  const cy = p.y - 27;
  for (const c of game.cores) {
    if (c.collected) continue;
    if (Math.hypot(p.x - c.x, cy - c.y) < 31) {
      c.collected = true;
      const key = `${game.level.id}:${c.idx}`;
      game.coreCollected.add(key);
      game.particles.pickupCore(c.x, c.y);
      game.audio.core();
      game.flash = { color: '#ffd36e', alpha: .16 };
      game.ui.showToast('CHRONO CORE', `${game.coreCollected.size} / ${game.level.cores.length} FRAGMENTS RECOVERED`, 1500);
    }
  }
  for (const e of game.energyOrbs) {
    if (e.collected) continue;
    if (Math.hypot(p.x - e.x, cy - e.y) < 27) {
      e.collected = true;
      game.timeEnergy = clamp(game.timeEnergy + 35, 0, 100);
      game.particles.pickupEnergy(e.x, e.y);
      game.audio.energy();
      game.ui.showToast('CHRONO ENERGY', '+35% RESERVE RESTORED', 1500);
    }
  }
}

function updateCheckpoints(game) {
  const p = game.player;
  if (!p) return;
  for (const c of game.checkpoints) {
    if (game.activeCheckpoints.has(c.id)) continue;
    if (Math.abs(p.x - c.x) < 32 && Math.abs(p.y - c.y) < 24) {
      game.activeCheckpoints.add(c.id);
      c.active = true;
      game.checkpointIndex = Math.max(game.checkpointIndex, c.id);
      game.respawn = { x: c.x, y: c.y };
      game.particles.checkpoint(c.x, c.y);
      game.audio.checkpoint();
      game.flash = { color: '#57f2ff', alpha: .16 };
      game.invuln = Math.max(game.invuln, .6);
      game.ui.setCheckpoint(game.checkpointIndex);
      game.ui.showToast('CHECKPOINT SECURED', 'Your next reconstruction point is locked.', 2100);
    }
  }
}

function updateHints(game, dt) {
  if (game.hintDelay > 0) {
    game.hintDelay -= dt;
    return;
  }
  game.hintCooldown = Math.max(0, game.hintCooldown - dt);
  if (game.hintCooldown > 0) return;
  const next = game.level.hints.find((h, i) => !game.hintsShown.has(i) && game.player.x >= h.triggerX);
  if (!next) return;
  const idx = game.level.hints.indexOf(next);
  game.hintsShown.add(idx);
  game.hintCooldown = 5.5;
  game.ui.showHint(next.text, 6800);
}

function updatePortal(game, dt) {
  const p = game.player;
  if (!p) return;
  if (Math.random() < dt * 7) game.particles.portal(game.portal.x, game.portal.y, game.level.palette.accent);
  if (Math.abs(p.x - game.portal.x) < 38 && p.y > game.portal.y - 112 && p.y < game.portal.y + 12) {
    game.completeLevel();
  }
}

/* ============================================================
   danger
   ============================================================ */

function checkDanger(game) {
  if (game.dead || game.god) return;
  const p = game.player;
  const box = playerRect(p, 4);
  if (game.invuln > 0) return;

  for (const p2 of game.projectiles) {
    if (circleRect(p2.x, p2.y, p2.radius || 5, box)) return killPlayer(game, 'bolt');
  }

  for (const h of game.hazards) {
    if (h.type === 'laser') {
      const cyc = ((game.worldTime + (h.phase || 0)) % h.period) / h.period;
      if (cyc < h.duty && rectsOverlap(box, { x: h.x, y: h.y, w: h.w, h: h.h })) {
        return killPlayer(game, 'laser');
      }
    } else if (h.type === 'saw') {
      const cyc = ((game.worldTime + (h.phase || 0)) % h.period) / h.period;
      const e = .5 - .5 * Math.cos(cyc * TAU);
      const x = h.x + (h.moveX || 0) * e;
      const y = h.y + (h.moveY || 0) * e;
      if (circleRect(x, y, (h.r || 18) + 2, box)) return killPlayer(game, 'saw');
    }
  }

  for (const e of game.enemies) {
    if (e.type === 'sentinel') {
      const body = { x: e.x - 20, y: e.y - 43, w: 40, h: 41 };
      if (rectsOverlap(box, body)) return killPlayer(game, 'sentinel');
    } else if (e.type === 'drone') {
      const bob = Math.sin(game.worldTime * 2 + e.phase) * (e.alert ? 1 : 5);
      if (circleRect(e.x, e.y + bob, 21, box)) return killPlayer(game, 'drone');
    }
  }
}

function rectsOverlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

function circleRect(cx, cy, r, rect) {
  const nx = clamp(cx, rect.x, rect.x + rect.w);
  const ny = clamp(cy, rect.y, rect.y + rect.h);
  const dx = cx - nx, dy = cy - ny;
  return dx * dx + dy * dy < r * r;
}

/* ============================================================
   death / respawn / completion helpers
   ============================================================ */

export function killPlayer(game, cause = 'fracture') {
  if (!game.player || game.dead || game.god) return;
  if (game.invuln > 0 && cause !== 'void') return;
  game.dead = true;
  game.deadTimer = 0;
  game.deathsThisRun += 1;
  game.deathWait = game.timeEnergy > 4 ? 3.4 : 2.4;
  game.player.alive = false;
  game.player.vx = 0;
  game.player.vy = 0;
  game.rewinding = false;
  game.input.rewind = false;
  game.ui.setRewinding(false);
  game.audio.rewindStop(true);
  game.audio.death();
  const px = game.player.x, py = game.player.y - 24;
  game.particles.death(px, py + 24, game.level.palette.accent, '#ff4f7b');
  game.camera.shake = game.reducedMotion ? 0 : 13;
  game.flash = { color: '#ff4f7b', alpha: .22 };
  game.ui.hideHint();
  game.ui.showDeath(game.timeEnergy, game.deathWait);
  game.history = game.history.slice(-Math.min(game.history.length, HISTORY_MAX));
}

export function respawnPlayer(game) {
  const deaths = game.deathsThisRun;
  game.audio.rewindStop(true);
  game.dead = false;
  game.deadTimer = 0;
  game.audio.setPaused(false);
  game.ui.hideDeath();
  game.ui.setRewinding(false);
  game.setupLevel(game.levelIndex, { fresh: false });
  game.deathsThisRun = deaths;
  game.timeEnergy = 100;
  game.invuln = 1.7;
  game.player.invuln = 1.7;
  game.echoTimer = 0;
  game.mode = 'playing';
  game.ui.showToast('RECONSTITUTED', game.checkpointIndex >= 0 ? 'Checkpoint timeline restored.' : 'Entry point restored.', 2100);
  game.flash = { color: '#57f2ff', alpha: .2 };
  game.audio.checkpoint();
  game.refreshHud(true);
}

/* ============================================================
   rewind
   ============================================================ */

export function startRewind(game) {
  if (game.rewinding || game.mode !== 'playing') return;
  if (game.timeEnergy <= 2) {
    game.ui.showToast('ENERGY DEPLETED', 'Find a chrono cell to rewind again.', 2000);
    game.audio.tone(120, .2, 'sine', .04, 70);
    return;
  }
  if (game.history.length < 5) {
    game.ui.showToast('TIMELINE TOO SHORT', 'Move for a moment before rewinding.', 1600);
    return;
  }
  const wasDead = game.dead;
  if (game.dead) {
    game.dead = false;
    game.deadTimer = 0;
    game.player.alive = true;
    game.ui.hideDeath();
  }
  game.rewinding = true;
  game.rewindCursor = game.history.length - 1;
  game.rewindAmount = 0;
  game.invuln = 0;
  game.input.jumpBuffer = 0;
  game.audio.rewindStart();
  game.audio.setPaused(false);
  game.ui.setRewinding(true);
  game.ui.setRewindSeconds('−0.00s');
  game.ui.hideHint();
  game.camera.shake = game.reducedMotion ? 0 : 2.4;
  game.flash = { color: '#57f2ff', alpha: .22 };
  if (wasDead) {
    game.particles.add({ type: 'ring', x: game.player.x, y: game.player.y - 26, size: 6, grow: 120, life: .55, color: '#57f2ff', width: 2.2 });
  }
}

function updateRewind(game, dt) {
  game.rewindCursor -= dt * SAMPLE_RATE * REWIND_PLAYBACK;
  game.timeEnergy = Math.max(0, game.timeEnergy - REWIND_DRAIN * dt);
  const maxIndex = game.history.length - 1;
  if (game.rewindCursor <= 0 || game.timeEnergy <= 0 || maxIndex < 1) {
    game.rewindCursor = Math.max(0, game.rewindCursor);
    endRewind(game);
    return;
  }
  applyInterpolated(game, game.rewindCursor);
  const latest = game.history[maxIndex];
  const current = snapshotAt(game, game.rewindCursor);
  game.rewindAmount = Math.max(0, (latest?.time || 0) - (current?.time || 0));
  game.particles.rewindBurst(game.player.x, game.player.y, '#57f2ff');
  game.audio.rewindTick(Math.min(1, game.rewindAmount / 5));
  if (Math.random() < dt * 20) {
    game.particles.add({
      type: 'glyph',
      x: game.player.x + (Math.random() - .5) * 60,
      y: game.player.y - 26 + (Math.random() - .5) * 70,
      vx: (Math.random() - .5) * 30,
      vy: (Math.random() - .5) * 30,
      life: .3 + Math.random() * .4,
      size: 1 + Math.random() * 2.5,
      color: '#57f2ff',
      drag: 1.5,
      spin: (Math.random() - .5) * 8
    });
  }
}

export function endRewind(game) {
  if (!game.rewinding) return;
  const maxIndex = game.history.length - 1;
  const idx = clamp(Math.floor(game.rewindCursor), 0, maxIndex);
  const snap = game.history[idx];
  if (snap) restoreSnapshot(game, snap);
  game.history = game.history.slice(0, idx + 1);
  game.rewindCursor = 0;
  game.rewinding = false;
  game.dead = false;
  game.deadTimer = 0;
  if (game.player) {
    game.player.alive = true;
    game.player.invuln = 1.15;
  }
  game.invuln = 1.15;
  game.sampleTimer = 0;
  game.echoTimer = ECHO_WINDOW;
  game.echoAnnounced = false;
  game.audio.rewindStop();
  game.ui.setRewinding(false);
  game.ui.setRewindSeconds('−0.00s');
  game.camera.shake = game.reducedMotion ? 0 : 3.5;
  game.flash = { color: '#57f2ff', alpha: .18 };
  game.particles.echoPulse(game.player.x, game.player.y, '#ffd36e');
  const hasEcho = game.platforms.some(p => p.kind === 'echo');
  if (hasEcho) {
    game.ui.showToast('ECHO WINDOW', 'Golden platforms are solid for 4.0 seconds.', 1900);
    game.audio.unlockSfx();
  }
  game.recordSnapshot(true);
  game.refreshHud(true);
}

/* ============================================================
   snapshot / restore
   ============================================================ */

export function captureSnapshot(game) {
  const p = game.player;
  return {
    time: game.worldTime,
    player: p ? {
      x: p.x, y: p.y, vx: p.vx, vy: p.vy, facing: p.facing,
      onGround: p.onGround, coyote: p.coyote, jumpBuffer: p.jumpBuffer,
      runPhase: p.runPhase, squash: p.squash, groundId: p.groundId,
      jumpCut: p.jumpCut, alive: p.alive
    } : null,
    enemies: game.enemies.map(e => ({ ...e })),
    projectiles: game.projectiles.map(p2 => ({ ...p2 })),
    platforms: game.platforms.map(p2 => ({
      state: p2.state, timer: p2.timer, fall: p2.fall
    }))
  };
}

function slotSnapshot(game, index) {
  return game.history[clamp(Math.floor(index), 0, game.history.length - 1)];
}

function snapshotAt(game, cursor) {
  const i = Math.floor(cursor);
  const a = game.history[i];
  const b = game.history[Math.min(game.history.length - 1, i + 1)];
  if (!a) return null;
  const t = clamp(cursor - i, 0, 1);
  return { ...a, time: lerp(a.time, b?.time ?? a.time, t) };
}

function applyInterpolated(game, cursor) {
  const i = Math.floor(cursor);
  const a = game.history[i];
  const b = game.history[Math.min(game.history.length - 1, i + 1)];
  if (!a) return;
  const t = clamp(cursor - i, 0, 1);
  game.worldTime = lerp(a.time, b?.time ?? a.time, t);

  if (a.player) {
    game.player = {
      ...game.player,
      ...a.player,
      x: lerp(a.player.x, b?.player?.x ?? a.player.x, t),
      y: lerp(a.player.y, b?.player?.y ?? a.player.y, t),
      vx: lerp(a.player.vx, b?.player?.vx ?? a.player.vx, t),
      vy: lerp(a.player.vy, b?.player?.vy ?? a.player.vy, t),
      invuln: 0,
      alive: true
    };
  }
  game.enemies = a.enemies.map((e, idx) => {
    const nb = b?.enemies?.[idx];
    if (!nb) return { ...e };
    return {
      ...e,
      x: lerp(e.x, nb.x, t),
      y: lerp(e.y, nb.y, t)
    };
  });
  game.projectiles = a.projectiles.map((p, idx) => {
    const np = b?.projectiles?.[idx];
    if (!np) return { ...p };
    return { ...p, x: lerp(p.x, np.x, t), y: lerp(p.y, np.y, t) };
  });
  game.platforms.forEach((p, idx) => {
    const ps = a.platforms[idx];
    if (!ps) return;
    p.state = ps.state;
    p.timer = ps.timer;
    p.fall = ps.fall;
  });
  game.updatePlatformState(0);
}

function restoreSnapshot(game, snap) {
  game.worldTime = snap.time;
  if (snap.player) {
    game.player = {
      ...game.player,
      ...snap.player,
      invuln: 1.15,
      alive: true
    };
  }
  game.enemies = snap.enemies.map(e => ({ ...e }));
  game.projectiles = snap.projectiles.map(p => ({ ...p }));
  game.platforms.forEach((p, idx) => {
    const ps = snap.platforms[idx];
    if (!ps) return;
    p.state = ps.state;
    p.timer = ps.timer;
    p.fall = ps.fall;
  });
  game.updatePlatformState(0);
}

