import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) errors.push('CONSOLE ' + m.text()); });

const results = [];
const check = (name, cond, detail = '') => {
  results.push({ name, ok: !!cond, detail });
  console.log(`${cond ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + detail : ''}`);
};
const s = () => page.evaluate(() => window.__TIME_REWIND__.state());
const ev = (fn, arg) => page.evaluate(fn, arg);
const sleep = ms => page.waitForTimeout(ms);

await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await sleep(700);

// enter game
await page.click('button[aria-label="Play"]').catch(async () => {
  await page.evaluate(() => window.__TIME_REWIND__.start(0));
});
await sleep(900);
let st = await s();
check('boot into level', st.mode === 'playing' && st.level === 0, JSON.stringify({ mode: st.mode, level: st.level }));

// unlock everything for tests
await ev(() => { window.__TIME_REWIND__.unlockAll(); window.__TIME_REWIND__.setGod(false); });

/* ---------- 1. movement ---------- */
await ev(() => window.__TIME_REWIND__.start(0));
await sleep(800);
const x0 = (await s()).x;
await page.keyboard.down('KeyD');
await sleep(700);
const x1 = (await s()).x;
await page.keyboard.up('KeyD');
check('movement right', x1 > x0 + 120, `x ${x0.toFixed(1)} -> ${x1.toFixed(1)}`);

/* ---------- 2. jump ---------- */
await ev(() => window.__TIME_REWIND__.teleport(200, 620));
await sleep(300);
const y0 = (await s()).y;
await page.keyboard.down('Space');
await sleep(290);
const yApex = (await s()).y;
await page.keyboard.up('Space');
await sleep(500);
const yLand = (await s()).y;
check('jump rises', y0 - yApex > 90, `feet ${y0.toFixed(1)} -> peakish ${yApex.toFixed(1)}`);
check('jump lands', Math.abs(yLand - 620) < 3, `landed ${yLand.toFixed(1)}`);

/* ---------- 3. rewind movement + energy ---------- */
await ev(() => window.__TIME_REWIND__.start(0));
await sleep(900);
await page.keyboard.down('KeyD');
await sleep(1100);
const beforeR = await s();
await page.keyboard.up('KeyD');
await page.keyboard.down('ShiftLeft');
await sleep(600);
const duringR = await s();
await page.keyboard.up('ShiftLeft');
await sleep(350);
const afterR = await s();
check('rewind flag active', duringR.rewinding === true, JSON.stringify({ rewinding: duringR.rewinding, echo: duringR.echo }));
check('rewind restores position', afterR.x < beforeR.x - 40, `x ${beforeR.x.toFixed(1)} -> ${afterR.x.toFixed(1)}`);
check('rewind drains energy', duringR.energy < beforeR.energy - 2, `energy ${beforeR.energy.toFixed(1)} -> ${duringR.energy.toFixed(1)}`);
check('rewind opens echo window', afterR.echo > 2, `echo ${afterR.echo}`);

/* ---------- 4. death then rewind revival ---------- */
await ev(() => window.__TIME_REWIND__.start(0));
await sleep(900);
await page.keyboard.down('KeyD');
await sleep(900);
await page.keyboard.up('KeyD');
const aliveX = (await s()).x;
await ev(() => window.__TIME_REWIND__.kill());
await sleep(250);
let deadSt = await s();
check('debug kill sets dead', deadSt.dead === true && deadSt.mode === 'playing', JSON.stringify({ dead: deadSt.dead, mode: deadSt.mode }));
const deathVisible = await page.locator('#death-screen').evaluate(el => !el.classList.contains('is-hidden')).catch(() => null);
check('death overlay visible', deathVisible === true, String(deathVisible));
await page.keyboard.down('ShiftLeft');
await sleep(500);
await page.keyboard.up('ShiftLeft');
await sleep(300);
const revived = await s();
check('rewind revives from death', revived.dead === false && revived.mode === 'playing', JSON.stringify({ dead: revived.dead, mode: revived.mode, x: revived.x, aliveX }));
check('revived near recorded position', Math.abs(revived.x - aliveX) < 240, `x ${revived.x.toFixed(1)} vs ${aliveX.toFixed(1)}`);

/* ---------- 5. checkpoint + respawn ---------- */
await ev(() => window.__TIME_REWIND__.start(0));
await sleep(700);
await ev(() => window.__TIME_REWIND__.teleport(505, 620));
await sleep(450);
st = await s();
check('checkpoint activates', st.checkpoint === 0, `checkpoint index ${st.checkpoint}`);
await ev(() => window.__TIME_REWIND__.kill());
await sleep(3900);
st = await s();
check('respawn after death', st.dead === false && st.mode === 'playing', JSON.stringify({ dead: st.dead, mode: st.mode }));
check('respawn at checkpoint', Math.abs(st.x - 505) < 4 && Math.abs(st.y - 620) < 4, `x ${st.x.toFixed(1)} y ${st.y.toFixed(1)}`);

/* ---------- 6. completion / unlock / save ---------- */
await ev(() => { window.__TIME_REWIND__.resetSave(); window.__TIME_REWIND__.unlockAll(); });
await ev(() => window.__TIME_REWIND__.start(9));
await sleep(800);
await ev(() => window.__TIME_REWIND__.teleport(1210, 590));
await sleep(700);
st = await s();
const saveData = await ev(() => JSON.parse(localStorage.getItem('time-rewind-save-v1')));
check('portal completes level', st.mode === 'complete', `mode ${st.mode}`);
check('completion saved', saveData && saveData.completed && saveData.completed['zero-hour'], JSON.stringify(saveData?.completed));
check('completion unlock count', saveData && saveData.unlocked === 10, `unlocked ${saveData?.unlocked}`);
const completeVisible = await page.locator('#complete-screen').evaluate(el => !el.classList.contains('is-hidden')).catch(() => null);
check('complete overlay visible', completeVisible === true, String(completeVisible));

/* ---------- 7. echo platforms ---------- */
await ev(() => window.__TIME_REWIND__.start(4));
await sleep(1100);
let preEcho = await s();
const echoPlats = preEcho.platforms.filter(p => p.kind === 'echo');
check('echo platforms exist in sector 5', echoPlats.length >= 3, `${echoPlats.length}`);
// hold rewind long enough to reach the past, release -> echo window
await page.keyboard.down('ShiftLeft');
await sleep(700);
await page.keyboard.up('ShiftLeft');
await sleep(250);
st = await s();
const echoAfter = st.platforms.filter(p => p.kind === 'echo');
check('echo window after rewind', st.echo > 2.5, `echo ${st.echo.toFixed(2)}`);
// teleport on first echo slab (its top) and verify support
const firstEcho = echoAfter[0];
await ev(({ x, y, w }) => window.__TIME_REWIND__.teleport(x + w / 2, y), { x: firstEcho.x, y: firstEcho.y, w: firstEcho.w });
await sleep(500);
st = await s();
check('stand on echo slab', Math.abs(st.y - firstEcho.y) < 2 && st.y < 600, `feet y ${st.y.toFixed(1)} slab ${firstEcho.y.toFixed(1)}`);
await sleep(4200);
st = await s();
check('echo fades after window', st.echo === 0, `echo ${st.echo}`);

/* ---------- 8. crumble platform + rewind restore ---------- */
await ev(() => window.__TIME_REWIND__.start(7));
await sleep(900);
const crumble = (await s()).platforms.find(p => p.kind === 'crumble');
await ev(({ x, y, w }) => window.__TIME_REWIND__.teleport(x + w / 2, y), { x: crumble.x, y: crumble.y, w: crumble.w });
await sleep(450);
st = await s();
const cr1 = st.platforms.find(p => p.kind === 'crumble');
check('crumble triggers on landing', cr1.state >= 1, `state ${cr1.state}`);
await sleep(1200);
st = await s();
const cr2 = st.platforms.find(p => p.kind === 'crumble');
check('crumble falls away', cr2.state === 2, `state ${cr2.state} y ${st.y.toFixed(1)}`);
// rewind should restore it
await page.keyboard.down('ShiftLeft');
await sleep(650);
await page.keyboard.up('ShiftLeft');
await sleep(350);
st = await s();
const cr3 = st.platforms.find(p => p.kind === 'crumble');
check('rewind restores crumble', cr3.state === 0, `state ${cr3.state}`);

/* ---------- 9. enemy projectile / collision ---------- */
await ev(() => { window.__TIME_REWIND__.start(1); window.__TIME_REWIND__.setGod(false); });
await sleep(900);
await ev(() => window.__TIME_REWIND__.teleport(830, 600));
await sleep(300);
await ev(() => {
  const g = window.__TIME_REWIND__.game;
  g.projectiles.push({ x: g.player.x, y: g.player.y - 28, vx: 0, vy: 0, life: 3, radius: 6, trail: 0 });
});
await sleep(150);
st = await s();
check('projectile kills player', st.dead === true, JSON.stringify({ dead: st.dead }));

/* ---------- 10. all levels load without errors ---------- */
for (let i = 0; i < 10; i++) {
  await ev((i) => window.__TIME_REWIND__.start(i), i);
  await sleep(350);
  const ls = await s();
  const ok = ls.mode === 'playing' && ls.level === i && ls.platforms.length > 0 && ls.y > 0;
  check(`sector ${i + 1} loads`, ok, `mode ${ls.mode} level ${ls.level} platforms ${ls.platforms.length}`);
}

console.log('\n--- JSON ---');
console.log(JSON.stringify({ results, errors }, null, 2));
await browser.close();

