import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const ctx = await browser.newContext({
  viewport: { width: 390, height: 844 },
  deviceScaleFactor: 2,
  isMobile: true,
  hasTouch: true,
  userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1'
});
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) errors.push(m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.waitForTimeout(900);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-menu.png' });
const vis = await page.evaluate(() => {
  const t = document.getElementById('touchControls');
  const cs = getComputedStyle(t);
  const r = t.getBoundingClientRect();
  return { display: cs.display, rect: { x: r.x, y: r.y, w: r.width, h: r.height }, bodyTouch: document.body.classList.contains('touch'), viewW: innerWidth, canvas: document.getElementById('game').getBoundingClientRect() };
});
console.log('touch', vis);
await page.click('button[aria-label="Play"]');
await page.waitForTimeout(1200);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-play.png' });
// touch right for 800ms
const right = page.locator('[data-touch="right"]');
const box = await right.boundingBox();
console.log('right box', box);
const s = () => page.evaluate(() => window.__TIME_REWIND__.state());
const before = await s();
await page.touchscreen.tap(box.x + box.width / 2, box.y + box.height / 2);
await page.waitForTimeout(100);
// pointer hold via dispatch
await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
await page.mouse.down();
await page.waitForTimeout(900);
await page.mouse.up();
const after = await s();
console.log('move', before.x, after.x);
// jump
const jb = await page.locator('[data-touch="jump"]').boundingBox();
await page.mouse.move(jb.x + jb.width / 2, jb.y + jb.height / 2);
await page.mouse.down();
await page.waitForTimeout(220);
const air = await s();
await page.mouse.up();
console.log('jump y', after.y, air.y);
// landscape
await page.setViewportSize({ width: 844, height: 390 });
await page.waitForTimeout(800);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-landscape.png' });
console.log('errors', errors);
await browser.close();

