import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errs=[]; page.on('pageerror',e=>errs.push(e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.waitForTimeout(500);
const res = await page.evaluate(() => {
  const api = window.__TIME_REWIND__, g = api.game;
  const out = {};
  // full 5s history then full rewind length
  api.setGod(true); api.start(0);
  for (let i=0;i<160;i++) api.step(1); // ~2.67s standing
  g.input.right = true;
  for (let i=0;i<160;i++) api.step(1); // 2.67s walking
  g.input.right = false;
  out.histBefore = g.history.length;
  out.before = { x: +g.player.x.toFixed(1), energy: +g.timeEnergy.toFixed(1), t: +g.worldTime.toFixed(2) };
  g.beginRewind();
  let frames = 0;
  while (g.rewinding && frames < 600) { api.step(1); frames++; }
  out.rewindFrames = frames;
  out.after = { x: +g.player.x.toFixed(1), energy: +g.timeEnergy.toFixed(1), t: +g.worldTime.toFixed(2), echo: +g.echoTimer.toFixed(2), hist: g.history.length };
  // crumble long rewind from death
  api.start(7); api.setGod(false);
  for (let i=0;i<30;i++) api.step(1);
  const cr = g.platforms.find(p=>p.kind==='crumble');
  api.teleport(cr.curX + cr.w/2, cr.curY);
  g.input.left=false;g.input.right=false;
  for (let i=0;i<100;i++) api.step(1); // crumble falls, player falls and dies
  out.crumbleMid = { state: cr.state, y: +g.player.y.toFixed(1), dead: g.dead, hist: g.history.length };
  g.beginRewind();
  frames=0;
  while (g.rewinding && frames < 600) { api.step(1); frames++; }
  out.crumbleAfter = { state: cr.state, y: +g.player.y.toFixed(1), dead: g.dead, echo: +g.echoTimer.toFixed(2), invuln: +g.invuln.toFixed(2), hist: g.history.length, frames };
  // moving platform restore
  api.start(1); api.setGod(true);
  for (let i=0;i<60;i++) api.step(1);
  const mp = g.platforms.find(p=>p.move);
  out.moveBefore = { x:+mp.curX.toFixed(1), y:+mp.curY.toFixed(1), wt:+g.worldTime.toFixed(2) };
  g.input.right=true;
  for (let i=0;i<80;i++) api.step(1);
  g.input.right=false;
  out.moveLater = { x:+mp.curX.toFixed(1), y:+mp.curY.toFixed(1), wt:+g.worldTime.toFixed(2) };
  g.beginRewind();
  frames=0;
  while (g.rewinding && frames < 600) { api.step(1); frames++; }
  out.moveAfter = { x:+mp.curX.toFixed(1), y:+mp.curY.toFixed(1), wt:+g.worldTime.toFixed(2), frames };
  return out;
});
console.log(JSON.stringify(res,null,2));
console.log('errors', errs);
await browser.close();

