import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });

// Desktop smoke
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGE ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.waitForTimeout(900);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/menu2.png' });
const menuTouch = await page.evaluate(() => ({ body: document.body.className, touchDisplay: getComputedStyle(document.getElementById('touchControls')).display }));
console.log('desktop menu', menuTouch, 'errors', errors);
await page.click('button[aria-label="Play"]');
await page.waitForTimeout(1200);
const playTouch = await page.evaluate(() => ({ body: document.body.className, touchDisplay: getComputedStyle(document.getElementById('touchControls')).display }));
console.log('desktop play', playTouch);
await page.keyboard.press('Escape');
await page.waitForTimeout(400);
const pauseTouch = await page.evaluate(() => ({ body: document.body.className, touchDisplay: getComputedStyle(document.getElementById('touchControls')).display, pauseHidden: document.getElementById('pauseScreen').classList.contains('is-hidden') }));
console.log('desktop pause', pauseTouch);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/pause2.png' });

// Echo visibility screenshot: start sector 5, hold rewind, screenshot inactive vs active
await page.evaluate(() => { window.__TIME_REWIND__.unlockAll(); window.__TIME_REWIND__.start(4); });
await page.waitForTimeout(900);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/echo-inactive.png' });
await page.keyboard.down('ShiftLeft');
await page.waitForTimeout(650);
await page.keyboard.up('ShiftLeft');
await page.waitForTimeout(300);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/echo-active.png' });

// Mobile menu/play
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
const mp = await ctx.newPage();
const merr = [];
mp.on('pageerror', e => merr.push(e.message));
mp.on('console', m => { if (m.type() === 'error') merr.push(m.text()); });
await mp.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await mp.waitForTimeout(900);
await mp.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-menu2.png' });
console.log('mobile menu', await mp.evaluate(() => ({ body: document.body.className, touchDisplay: getComputedStyle(document.getElementById('touchControls')).display })));
await mp.click('button[aria-label="Play"]');
await mp.waitForTimeout(1300);
await mp.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-play2.png' });
console.log('mobile play', await mp.evaluate(() => ({ body: document.body.className, touchDisplay: getComputedStyle(document.getElementById('touchControls')).display })));
// touch rewind works
const rb = await mp.locator('[data-touch="rewind"]').boundingBox();
const stateBefore = await mp.evaluate(() => window.__TIME_REWIND__.state());
await mp.mouse.move(rb.x + rb.width / 2, rb.y + rb.height / 2);
await mp.mouse.down();
await mp.waitForTimeout(650);
const stateDuring = await mp.evaluate(() => window.__TIME_REWIND__.state());
await mp.mouse.up();
await mp.waitForTimeout(250);
const stateAfter = await mp.evaluate(() => window.__TIME_REWIND__.state());
console.log('touch rewind', { x0: stateBefore.x, rewinding: stateDuring.rewinding, energy: stateDuring.energy, afterEcho: stateAfter.echo, afterX: stateAfter.x });
// mobile death overlay text
await mp.evaluate(() => window.__TIME_REWIND__.kill());
await mp.waitForTimeout(300);
await mp.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-death.png' });
console.log('mobile death', await mp.evaluate(() => ({ death: !document.getElementById('death-prompt').classList.contains('is-hidden'), action: document.querySelector('.death-action').innerText })));
console.log('mobile errors', merr);
await browser.close();

