import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGE ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
const results = [];
const check = (name, ok, detail='') => { results.push({name, ok:!!ok, detail}); console.log(`${ok?'PASS':'FAIL'} ${name}${detail?' :: '+detail:''}`); };
const s = () => page.evaluate(() => window.__TIME_REWIND__.state());
const sleep = ms => page.waitForTimeout(ms);

await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await sleep(700);

// fresh save
await page.evaluate(() => localStorage.removeItem('time-rewind-save-v1'));
await page.reload({ waitUntil: 'networkidle' });
await sleep(700);

check('menu visible', await page.locator('#menuScreen').evaluate(el => !el.classList.contains('is-hidden')));
check('touch controls hidden on menu', (await page.locator('#touchControls').evaluate(el => getComputedStyle(el).display)) === 'none');

// protocol
await page.click('#btn-how');
await sleep(300);
check('protocol opens', await page.locator('#howScreen').evaluate(el => !el.classList.contains('is-hidden')));
await page.click('#howScreen [data-action="menu"]');
await sleep(300);
check('protocol back', await page.locator('#menuScreen').evaluate(el => !el.classList.contains('is-hidden')));

// settings
await page.click('#btn-settings');
await sleep(300);
check('settings opens', await page.locator('#settingsScreen').evaluate(el => !el.classList.contains('is-hidden')));
const audioBefore = await page.evaluate(() => window.__TIME_REWIND__.save.settings.audio);
await page.click('#toggle-audio');
await sleep(200);
const audioAfter = await page.evaluate(() => window.__TIME_REWIND__.save.settings.audio);
check('audio toggle', audioBefore !== audioAfter, `${audioBefore} -> ${audioAfter}`);
const motionBefore = await page.evaluate(() => window.__TIME_REWIND__.save.settings.reducedMotion);
await page.click('#toggle-motion');
await sleep(200);
const motionAfter = await page.evaluate(() => window.__TIME_REWIND__.save.settings.reducedMotion);
check('motion toggle', motionBefore !== motionAfter, `${motionBefore} -> ${motionAfter}`);
const fxBefore = await page.evaluate(() => window.__TIME_REWIND__.save.settings.screenFx);
await page.click('#toggle-fx');
await sleep(200);
