import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) errors.push(m.text()); });
const sleep = ms => page.waitForTimeout(ms);
const s = () => page.evaluate(() => window.__TIME_REWIND__.state());
const center = async sel => { const b = await page.locator(sel).boundingBox(); return { x: b.x + b.width / 2, y: b.y + b.height / 2 }; };
const hold = async (sel, ms) => { const c = await center(sel); await page.mouse.move(c.x, c.y); await page.mouse.down(); await sleep(ms); await page.mouse.up(); };

await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await sleep(700);
await page.click('button[aria-label="Play"]');
await sleep(1400);

// jump test
let st0 = await s();
await hold('[data-touch="jump"]', 280);
await sleep(50);
let st1 = await s();
console.log('jump', { from: st0.y, to: st1.y, airborne: st1.y < st0.y - 40 });
await sleep(800);

// right movement + jump to next platform
await page.evaluate(() => window.__TIME_REWIND__.teleport(320, 620));
await sleep(300);
const rc = await center('[data-touch="right"]');
await page.mouse.move(rc.x, rc.y);
await page.mouse.down();
await sleep(120);
await hold('[data-touch="jump"]', 300);
await sleep(700);
await page.mouse.up();
let st2 = await s();
console.log('move+jump', { x: st2.x, y: st2.y, mode: st2.mode });
await sleep(400);

// touch controls hidden on pause and visible on resume
await page.click('#hud-pause');
await sleep(350);
const pauseDisp = await page.locator('#touchControls').evaluate(el => getComputedStyle(el).display);
await page.click('#btn-resume');
await sleep(350);
const resumeDisp = await page.locator('#touchControls').evaluate(el => getComputedStyle(el).display);
console.log('pause touch', { pauseDisp, resumeDisp });

// death overlay and touch rewind resurrect
await sleep(1400);
await page.evaluate(() => window.__TIME_REWIND__.kill());
await sleep(300);
const deathVis = await page.locator('#death-prompt').evaluate(el => !el.classList.contains('is-hidden'));
const deathAction = await page.locator('.death-action').innerText();
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-death2.png' });
const before = await s();
await hold('[data-touch="rewind"]', 600);
await sleep(350);
const after = await s();
console.log('death+rewind', { deathVis, deathAction, beforeDead: before.dead, afterDead: after.dead, afterX: after.x, echo: after.echo });

// landscape
await page.evaluate(() => window.__TIME_REWIND__.start(0));
await sleep(900);
await page.setViewportSize({ width: 844, height: 390 });
await sleep(800);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-landscape2.png' });
const landDisp = await page.locator('#touchControls').evaluate(el => getComputedStyle(el).display);
console.log('landscape touch', landDisp);
console.log('errors', errors);
await browser.close();

