import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.waitForTimeout(500);
const out = await page.evaluate(() => {
  const api = window.__TIME_REWIND__, g = api.game;
  const res = {};
  // Enemy restore on level 4
  api.setGod(true); api.start(3);
  for (let i=0;i<10;i++) api.step(1);
  const sent = g.enemies.find(e=>e.type==='sentinel');
  res.sent0 = +sent.x.toFixed(1);
  for (let i=0;i<70;i++) api.step(1);
  res.sent1 = +sent.x.toFixed(1);
  g.beginRewind();
  let f=0; while (g.rewinding && f<400) { api.step(1); f++; }
  res.sent2 = +sent.x.toFixed(1);
  res.sentFrames = f;
  // Projectile appears then rewinds away
  api.start(0);
  for (let i=0;i<40;i++) api.step(1);
  g.projectiles.push({x:600,y:400,vx:0,vy:0,life:3,radius:6,trail:0});
  for (let i=0;i<10;i++) api.step(1);
  res.proj1 = g.projectiles.length;
  g.beginRewind();
  f=0; while (g.rewinding && f<250) { api.step(1); f++; }
  res.proj2 = g.projectiles.length;
  // Pickups, energy and checkpoint are excluded from rewind
  api.start(0);
  for (let i=0;i<20;i++) api.step(1);
  // stand under first core and collect it
  const core = g.cores[0];
  api.teleport(core.x, 620);
  for (let i=0;i<4;i++) api.step(1);
  res.coreCollected = g.coreCollected.size;
  res.energyBefore = +g.timeEnergy.toFixed(1);
  // checkpoint
  api.teleport(505, 620);
  for (let i=0;i<4;i++) api.step(1);
  res.cp = g.checkpointIndex;
  // eat energy? set lower then rewind; rewind should not refill
  g.timeEnergy = 40;
  for (let i=0;i<12;i++) api.step(1);
  g.beginRewind();
  f=0; while (g.rewinding && f<260) { api.step(1); f++; }
  res.coreAfter = g.coreCollected.size;
  res.cpAfter = g.checkpointIndex;
  res.energyAfter = +g.timeEnergy.toFixed(1);
  res.coresState = g.cores.map(c=>c.collected);
  // echo platform faint-but-visible sanity (draw data only)
  res.echoKinds = api.getLevel(4).platforms.filter(p=>p.kind==='echo').length;
  return res;
});
console.log(JSON.stringify(out,null,2));
await browser.close();

