await sleep(700);

check('menu visible', await page.locator('#menuScreen').evaluate(el => !el.classList.contains('is-hidden')));
check('touch controls hidden on menu', (await page.locator('#touchControls').evaluate(el => getComputedStyle(el).display)) === 'none');

