import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const errors = [];
const results = [];
const check = (name, ok, detail='') => { results.push({name, ok:!!ok, detail}); console.log(`${ok?'PASS':'FAIL'} ${name}${detail?' :: '+detail:''}`); };

const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => errors.push('PAGE ' + e.message));
page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.type().toUpperCase() + ' ' + m.text()); });
page.on('response', r => { if (r.status() >= 400 && new URL(r.url()).origin === 'http://localhost:3002') errors.push(`HTTP ${r.status()} ${r.url()}`); });

await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.removeItem('time-rewind-save-v1'));
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(800);

const logo = await page.locator('.logo').boundingBox();
const copy = await page.locator('.menu-copy').boundingBox();
check('title logo fits viewport', logo && logo.x + logo.width <= 1440, JSON.stringify(logo));
check('title logo width sane', logo && logo.width > 300 && logo.width <= copy.width + 1, `logoW=${logo?.width?.toFixed(1)} copyW=${copy?.width?.toFixed(1)}`);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-desktop-menu.png' });

await page.click('#btn-play');
await page.waitForTimeout(1200);
let st = await page.evaluate(() => window.__TIME_REWIND__.state());
check('desktop gameplay starts', st.mode === 'playing', JSON.stringify(st));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-desktop-play.png' });

await page.waitForTimeout(2600);
const introVisible = await page.locator('#levelIntro').evaluate(el => !el.classList.contains('is-hidden') && getComputedStyle(el).opacity !== '0');
check('level intro fades out', !introVisible);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-desktop-world.png' });

await page.keyboard.down('d');
await page.waitForTimeout(900);
await page.keyboard.up('d');
const before = await page.evaluate(() => ({ x: window.__TIME_REWIND__.game.player.x, e: window.__TIME_REWIND__.game.timeEnergy }));
await page.keyboard.down('r');
await page.waitForTimeout(600);
await page.keyboard.up('r');
await page.waitForTimeout(250);
const after = await page.evaluate(() => ({ x: window.__TIME_REWIND__.game.player.x, e: window.__TIME_REWIND__.game.timeEnergy, snap: window.__TIME_REWIND__.game.history.length }));
check('rewind restores player', after.x < before.x - 20, `x ${before.x.toFixed(1)} -> ${after.x.toFixed(1)}`);
check('rewind drains energy', after.e < before.e, `e ${before.e.toFixed(1)} -> ${after.e.toFixed(1)}`);
check('history capped <=150', after.snap <= 150, `snap=${after.snap}`);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-desktop-rewind.png' });

await page.click('#hud-pause');
await page.waitForTimeout(400);
check('pause overlay', (await page.evaluate(() => window.__TIME_REWIND__.state())).mode === 'paused');
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-desktop-pause.png' });
await page.click('#btn-resume');
await page.waitForTimeout(400);

await page.evaluate(() => window.__TIME_REWIND__.kill());
await page.waitForTimeout(500);
check('death overlay visible', await page.locator('#death-prompt').evaluate(el => !el.classList.contains('is-hidden')));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-desktop-death.png' });
await page.waitForTimeout(900);
await page.keyboard.down('r');
await page.waitForTimeout(500);
await page.keyboard.up('r');
await page.waitForTimeout(300);
st = await page.evaluate(() => window.__TIME_REWIND__.state());
check('rewind revives on desktop', !st.dead && st.mode === 'playing', JSON.stringify(st));
check('death prompt hidden after revive', await page.locator('#death-prompt').evaluate(el => el.classList.contains('is-hidden')));

const mobile = await browser.newPage({ viewport: { width: 844, height: 390 }, hasTouch: true, isMobile: true });
mobile.on('pageerror', e => errors.push('MOBILE PAGE ' + e.message));
mobile.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errors.push('MOBILE ' + m.type().toUpperCase() + ' ' + m.text()); });
await mobile.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await mobile.evaluate(() => localStorage.removeItem('time-rewind-save-v1'));
await mobile.reload({ waitUntil: 'networkidle' });
await mobile.waitForTimeout(900);
await mobile.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-mobile-landscape-menu.png' });
const playBox = await mobile.locator('#btn-play').boundingBox();
check('mobile landscape play button visible', !!playBox, JSON.stringify(playBox));
await mobile.tap('#btn-play');
await mobile.waitForTimeout(1600);
st = await mobile.evaluate(() => window.__TIME_REWIND__.state());
check('mobile landscape gameplay', st.mode === 'playing', JSON.stringify(st));
const touchDisp = await mobile.locator('#touchControls').evaluate(el => getComputedStyle(el).display);
check('touch controls visible while playing', touchDisp !== 'none', touchDisp);
await mobile.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-mobile-landscape-play.png' });
await mobile.evaluate(() => window.__TIME_REWIND__.kill());
await mobile.waitForTimeout(700);
check('mobile landscape death overlay', await mobile.locator('#death-prompt').evaluate(el => !el.classList.contains('is-hidden')));
await mobile.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-mobile-landscape-death.png' });
const prompt = await mobile.locator('#death-prompt').boundingBox();
check('death prompt fits landscape', prompt && prompt.y >= 0 && prompt.y + prompt.height <= 390, JSON.stringify(prompt));
await mobile.waitForTimeout(800);
let box = await mobile.locator('[data-touch="rewind"]').boundingBox();
await mobile.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
await mobile.mouse.down();
await mobile.waitForTimeout(500);
await mobile.mouse.up();
await mobile.waitForTimeout(400);
st = await mobile.evaluate(() => window.__TIME_REWIND__.state());
check('mobile death rewind resumes', !st.dead && st.mode === 'playing', JSON.stringify(st));
check('mobile death prompt hidden', await mobile.locator('#death-prompt').evaluate(el => el.classList.contains('is-hidden')));

const portrait = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
portrait.on('pageerror', e => errors.push('PORTRAIT PAGE ' + e.message));
await portrait.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await portrait.evaluate(() => localStorage.removeItem('time-rewind-save-v1'));
await portrait.reload({ waitUntil: 'networkidle' });
await portrait.waitForTimeout(900);
await portrait.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-mobile-menu.png' });
const logoBox = await portrait.locator('.logo').boundingBox();
check('portrait logo fits', logoBox && logoBox.x >= 0 && logoBox.x + logoBox.width <= 390, JSON.stringify(logoBox));
await portrait.tap('#btn-play');
await portrait.waitForTimeout(1500);
await portrait.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-mobile-portrait-play.png' });

console.log('\nERRORS', JSON.stringify(errors, null, 2));
const failed = results.filter(r => !r.ok);
console.log(`\nRESULT ${results.length - failed.length}/${results.length} checks pass`);
await browser.close();
process.exit(failed.length || errors.length ? 1 : 0);

